    ["Padding"] = "Preenchimento",
    ["Party, Raid, and Mythic Raid Group Frame layout, bars, auras, indicators, scope overrides and positions"] = "Layout do quadro, barras, auras, indicadores, substituições de escopo e posições do grupo de grupo, Raid e Mythic Raid",
    ["Position"] = "Posição",
    ["Positions class bar ABOVE Essential Cooldowns"] = "Barra de classe de posições ACIMA dos cooldowns essenciais",
    ["Preserve HP color on all unit frames"] = "Preservar a cor HP em todas as estruturas da unidade",
    ["Press Ctrl+C to copy:"] = "Pressione Ctrl+C para copiar:",
    ["Preview follows the current castbar visibility, icon, text, and global color settings."] = "A visualização segue a visibilidade atual da barra de lançamento, ícone, texto e configurações globais de cores.",
    ["Profile actions"] = "Ações de perfil",
    ["Quick Setup: Detached Class Bar"] = "Configuração rápida: barra de classe separada",
    ["Reload"] = "Recarregar",
    ["Rows"] = "Linhas",
    ["Same setting as each unit page > Transparency. It uses this same HP track color; off here means at least one unit frame is off."] = "Mesma configuração de cada página de unidade > Transparência. Ele usa a mesma cor de trilha HP; desligado aqui significa que pelo menos um quadro da unidade está desligado.",
    ["Secret aura (name/fingerprint matched)"] = "Aura secreta (nome/fingerprint correspondente)",
    ["Select:"] = "Selecione:",
    ["Set Bar Background Tint to white and enable Custom color in Dark Mode. If black, enable Preserve HP color on all unit frames."] = "Defina a tonalidade do fundo da barra como branco e ative a cor personalizada no modo escuro. Se for preto, ative Preservar cor HP em todas as estruturas da unidade.",
    ["Setup Now"] = "Configurar agora",
    ["Slot"] = "Slot",
    ["Some layout changes rebuild frames, while visual changes apply instantly. If needed, close and reopen the menu or reload after large profile/import changes."] = "Algumas alterações de layout reconstroem quadros, enquanto as alterações visuais são aplicadas instantaneamente. Se necessário, feche e reabra o menu ou recarregue após grandes alterações no perfil/import.",
    ["Syncs & anchors power bar to class resources"] = "Sincroniza e ancora a barra de energia aos recursos da classe",
    ["The active profile is saved per character. New characters start on this profile instead of Default."] = "O perfil ativo é salvo por personagem. Novos personagens começam com este perfil em vez de Default.",
    ["This layer is off in settings and cannot be shown in preview."] = "Esta camada está desativada nas configurações e não pode ser mostrada na visualização.",
    ["Type a name here before creating or copying a profile."] = "Digite um nome aqui antes de criar ou copiar um perfil.",
    ["Undo"] = "Desfazer",
    ["Unit Frame Preview"] = "Visualização do quadro da unidade",
    ["Unit frame status icons are on each unit page. Group frame indicators are in Group Frames > Indicators."] = "Os ícones de status da estrutura da unidade estão em cada página da unidade. Os indicadores de quadro de grupo estão em Quadros de grupo > Indicadores.",
    ["Use /msuf to open MSUF2. The Dashboard also contains reset, support, profile, and scale tools."] = "Use /msuf para abrir MSUF2. O Dashboard também contém ferramentas de redefinição, suporte, perfil e escala.",
    ["Use Dashboard > Reset Positions for frame movers. Use Profiles only when you want to reset, copy, import, or replace profile data."] = "Use Painel > Redefinir posições para movimentadores de quadros. Use Perfis somente quando desejar redefinir, copiar, importar ou substituir dados de perfil.",
    ["Use Global Style > Bars for highlight borders and Group Frames > Indicators for role, threat, dispel, spell, corner, and raid-marker indicators."] = "Use Estilo Global > Barras para destacar bordas e Quadros de Grupo > Indicadores para indicadores de função, ameaça, dissipação, feitiço, canto e marcador de ataque.",
    ["Use Group Frames > Layout for size and spacing, Buffs & Debuffs for aura clutter, and Indicators for fixed-position status icons."] = "Use Quadros de grupo > Layout para tamanho e espaçamento, Buffs e Debuffs para desordem de aura e Indicadores para ícones de status de posição fixa.",
    ["Use Group Frames pages: Layout for size/growth/sorting, Health & Text for bars/text, Buffs & Debuffs for auras, and Indicators for status icons."] = "Use páginas de quadros de grupo: Layout para tamanho/growth/sorting, Saúde e Texto para barras/text, Buffs e Debuffs para auras e Indicadores para ícones de status.",
    ["Use MSUF Edit Mode to drag a single unit frame. Use the unit page > Anchoring when you need exact anchor targets or X/Y values."] = "Use o modo de edição MSUF para arrastar um único quadro de unidade. Use a página da unidade > Ancoragem quando precisar de alvos de âncora exatos ou valores X/Y.",
    ["Use MSUF Edit Mode to drag supported castbars. Per-unit castbar enable/icon/text options are on each unit page; shared castbar style is in Global Style > Castbar."] = "Use o modo de edição MSUF para arrastar barras de cast suportadas. As opções de castbar enable/icon/text por unidade estão na página de cada unidade; O estilo castbar compartilhado está em Global Style > Castbar.",
    ["Use MSUF Edit Mode to drag the player frame. For exact anchor or X/Y values, open Player > Anchoring after that."] = "Use o modo de edição MSUF para arrastar o quadro do player. Para valores exatos de âncora ou X/Y, abra Player > Anchoring depois disso.",
    ["Use the Dashboard scale controls for menu scale or UI scale. You can also resize the MSUF2 window from its corner."] = "Use os controles de escala do painel para escala de menu ou escala UI. Você também pode redimensionar a janela MSUF2 a partir do canto.",
    ["Use the unit page for per-unit castbar toggles and Global Style > Castbar for shared textures, direction, GCD, text, and interrupt options."] = "Use a página da unidade para alternar a barra de lançamento por unidade e Estilo Global > Barra de lançamento para texturas compartilhadas, direção, GCD, texto e opções de interrupção.",
    ["Use this if HP Bar fade makes the empty health area disappear or look black. It keeps the same HP track color from Colors."] = "Use isto se o desbotamento da barra HP fizer com que a área de saúde vazia desapareça ou pareça preta. Ele mantém a mesma cor da faixa HP de Colors.",
    ["Value:"] = "Valor:",
    ["View"] = "Ver",
    ["Welcome to Class Resources!"] = "Bem-vindo aos Recursos de Classe!",
    ["WoW blocks some protected frame changes in combat. Leave combat, then apply layout, anchoring, enable/disable, profile, or protected-frame changes."] = "WoW bloqueia algumas alterações de quadros protegidos em combate. Saia do combate e aplique alterações de layout, ancoragem, ativação de /disable, perfil ou quadro protegido.",
    ["bottom"] = "inferior",
    ["change background color unit frames"] = "alterar cor de fundo dos quadros de unidade",
    ["class-resource layout, behavior, style, auto-hide, detached power bar and alternative mana settings"] = "layout de recursos de classe, comportamento, estilo, ocultação automática, barra de energia separada e configurações alternativas de mana",
    ["click layers to hide - drag preview elements - arrows nudge selected"] = "clique nas camadas para ocultar - arraste os elementos de visualização - as setas deslocam a seleção",
    ["frame colors, class/NPC colors, power colors, castbar colors, aura colors and gameplay color settings"] = "cores de quadro, cores class/NPC, cores de energia, cores de castbar, cores de aura e configurações de cores de jogo",
    ["gameplay enhancement settings such as combat text, crosshair and click-cast behavior"] = "configurações de aprimoramento de jogabilidade, como texto de combate, mira e comportamento de clique",
    ["gf_layout"] = "gf_layout",
    ["global castbar behavior, textures, GCD, boss castbar and interrupt indicator settings"] = "comportamento global do castbar, texturas, GCD, boss castbar e configurações do indicador de interrupção",
    ["language/menu behavior, update pacing, tooltips, Blizzard-frame handling, minimap icon, sounds and range-fade settings"] = "Comportamento do idioma /menu, ritmo de atualização, dicas de ferramentas, manipulação de quadros Blizzard, ícone do minimapa, sons e configurações de desvanecimento de alcance",
    ["none"] = "nenhum",
    ["optional style/module settings such as MSUF Style and dropdown style"] = "configurações opcionais de style/module, como estilo MSUF e estilo suspenso",
    ["scope disabled"] = "escopo desativado",
    ["shared"] = "compartilhado",
    ["shared bar textures, gradients, rounded frame corners, absorb display, outlines, highlight borders, power smoothing and all per-unit/group bar overrides"] = "texturas de barra compartilhadas, gradientes, cantos de moldura arredondados, exibição de absorção, contornos, bordas de realce, suavização avançada e todas as substituições de barra por unidade /group",
    ["shared font family, text style, name/power text coloring, name shortening and all per-unit/group font overrides"] = "família de fontes compartilhada, estilo de texto, coloração de texto name/power, encurtamento de nome e todas as substituições de fonte por unidade/group",
    ["the entire active profile"] = "todo o perfil ativo",
    ["uf_target"] = "uf_target",
    ["–"] = "–",
}
for k, v in pairs(MSUF_LOCALE_COVERAGE_ptBR) do
