L["|cffffd700MSUF:|r Group Frames reset to defaults."] = "|cffffd700MSUF:|r Quadros de grupo redefinidos para os padrões."
L["|cffffd700MSUF:|r Preserve HP color uses the same HP track color from Colors, but some bar textures may look different."] = "|cffffd700MSUF:|r Preservar cor de HP usa a mesma cor da trilha de HP em Cores, mas algumas texturas de barra podem parecer diferentes."
L["Click a handle to select - drag custom layers - arrow keys nudge selected; Blizzard is locked"] = "Clique em uma alça para selecionar - arraste camadas personalizadas - as setas movem a seleção; Blizzard está bloqueado"
L["Copy categories"] = "Categorias de cópia"
L["Copy Selected"] = "Copiar selecionados"
L["Custom Anchor Frame"] = "Quadro de âncora personalizado"
L["Custom anchor target (mouse picker)"] = "Alvo de âncora personalizado (seletor do mouse)"
L["Don't show again"] = "Não mostrar novamente"
L["Frame disabled"] = "Quadro desativado"
L["Growth Direction"] = "Direção de crescimento"
L["Preserve HP color keeps the HP fill color while layer fade is active and draws missing health separately with the same HP track color from Colors.\n\nThis can help when HP Bar fade makes the empty HP area disappear or look black. Some custom textures may still look flat, dark, or different while this option is enabled."] = "Preservar cor de HP mantém a cor de preenchimento de HP enquanto o desvanecimento de camada está ativo e desenha a vida ausente separadamente com a mesma cor da trilha de HP em Cores.\n\nIsso pode ajudar quando o desvanecimento da barra de HP faz a área vazia desaparecer ou parecer preta. Algumas texturas personalizadas ainda podem parecer planas, escuras ou diferentes com esta opção ativada."
L["Reset %s to defaults?\n\nThis resets %s for the active profile. Defaults are read from the current MSUF factory profile, so future default changes are used automatically."] = "Redefinir %s para os padrões?\n\nIsso redefine %s para o perfil ativo. Os padrões são lidos do perfil de fábrica atual do MSUF, então futuras alterações padrão serão usadas automaticamente."
L["Reset %s to defaults?\n\nThis resets the entire active profile '%s' to the current MSUF factory defaults. Every menu in that profile will be affected."] = "Redefinir %s para os padrões?\n\nIsso redefine todo o perfil ativo '%s' para os padrões de fábrica atuais do MSUF. Todos os menus desse perfil serão afetados."
L["Reset Scopes"] = "Redefinir escopos"

