L["Added Focus Target frame support across unit settings, edit mode, menu previews, copy targets, text options, icons, and runtime refreshes."] = "Adicionado suporte ao quadro Alvo do foco em configurações de unidade, modo de edição, prévias, destinos de cópia, opções de texto, ícones e atualizações runtime."
L["Added improved on/off switch visuals."] = "Adicionados visuais melhorados para switches on/off."
