L["Added redesigned Menu2 card layout across unit, group, aura, indicator, bar, and advanced pages."] = "Adicionado layout redesenhado de cards Menu2 em páginas de unidade, grupo, aura, indicador, barras e avançado."
L["Added Rounded Frames with per-surface controls for unit frames, group frames, bars, highlights, overlays, absorbs, and indicators."] = "Adicionados quadros arredondados com controles por superfície para unidades, grupos, barras, realces, overlays, absorções e indicadores."
