L["Blizzard mode lets WoW place the selected aura types. MSUF Custom mode lets MSUF control aura size, growth, position, filters, and styling. Dispel Glow is unavailable only for Group Frame scopes where Blizzard controls the aura layer."] = "O modo Blizzard deixa o WoW posicionar os tipos de aura selecionados. O modo MSUF Personalizado permite ao MSUF controlar tamanho, crescimento, posição, filtros e estilo. Brilho de dissipação fica indisponível apenas em escopos de quadros de grupo onde a Blizzard controla a camada de auras."
L["Blizzard renders cooldown/stack text for native Buffs and Debuffs. These text overlay fields only affect custom icons."] = "A Blizzard renderiza o texto de recarga e acúmulos de benefícios e penalidades nativos. Estes campos de texto afetam apenas ícones personalizados."
