L["EM_HELP_BTN"] = "? Ajuda"
L["EM_HELP_BTN_TIP"] = "Abre a configuração guiada completa do MSUF\nno capítulo do modo de edição."
L["EM_HELP_CDM"] = "|cff60a5ffCDM|r alterna a âncora global do Essential Cooldown Manager. |cff60a5ffAnchor|r abre o seletor de âncora; passe sobre um quadro nomeado, segure Ctrl e clique esquerdo para usá-lo como âncora global. Escolher uma âncora personalizada desativa o CDM."
L["EM_HELP_COPYTO"] = "Em popups de unidade e barra de lançamento, |cff60a5ffCopy To|r copia as configurações do popup atual para outro alvo. A cópia de quadros de unidade mantém posição e âncora do alvo; a cópia de barras mantém os deslocamentos X/Y do alvo."
L["EM_HELP_DRAG"] = "Segure o botão esquerdo do mouse em uma sobreposição de movedor e arraste. O quadro real acompanha o movedor, e a leitura X/Y abaixo da sobreposição mostra o deslocamento atual na tela. Solte para salvar a posição."
L["EM_HELP_EXIT"] = "|cff60a5ffExit|r sai do modo de edição e mantém as alterações atuais. Entrar em combate também sai do modo de edição. Escape fecha ou cancela o popup; o botão Exit do HUD é a forma normal de sair."
L["EM_HELP_NUDGE"] = "As setas movem o alvo ativo. Prioridade: alça de prévia selecionada, popup de barra aberto, popup de aura aberto e depois o quadro de unidade selecionado. Passo: 1 px, Shift = 5 px, Ctrl = 10 px, Alt = passo atual da grade."
L["EM_HELP_OPACITY"] = "Role no controle |cff60a5ffBG ##%|r para mudar apenas a opacidade do fundo do modo de edição. Isso não altera o alfa do quadro de unidade nem a visibilidade salva."
L["EM_HELP_POPUP"] = "Clique esquerdo em um movedor sem arrastar abre o popup de edição. Popups de unidade editam tamanho, posição, âncoras de texto, configurações de poder separado e opções de copiar para unidade. Movedores de barra e aura abrem popups próprios."
L["EM_HELP_PREVIEW"] = "|cff60a5ffPreview|r alterna dados de marcador para alvo, foco, alvo do alvo, ajudante, chefes e prévias de barras ausentes enquanto o modo de edição está ativo. |cff60a5ffAuras|r alterna ícones de prévia de aura e caixas de movedor de aura."
L["EM_HELP_SNAP"] = "A grade é uma ajuda visual. Clique esquerdo em |cff60a5ffGrid ##px|r alterna linhas da grade; rolar muda o espaçamento. |cff60a5ffSnap|r é separado: quando ativo, movedores arrastados encaixam no centro da tela ou em bordas/centros de outros movedores visíveis, com guias laranja."
L["EM_HELP_TITLE"] = "Modo de edição - Referência rápida"
L["EM_HELP_UNDO"] = "|cff60a5ffUndo|r e |cff60a5ffRedo|r restauram alterações recentes do modo de edição capturadas antes de arrastos, ajustes com setas e alterações em popups. |cff60a5ffCancel All|r pede confirmação, restaura a captura anterior à entrada no modo de edição e depois sai."
