L["Blizzard mode lets WoW place the selected aura types. MSUF Custom mode lets MSUF control aura size, growth, position, filters, and styling. MSUF Dispel Highlights keep Blizzard icons while allowing MSUF's dispel border, glow, and overlay visuals."] = "O modo Blizzard deixa o WoW posicionar os tipos de aura selecionados. O modo MSUF Personalizado permite ao MSUF controlar tamanho, crescimento, posição, filtros e estilo. Os destaques de dissipação do MSUF mantêm os ícones da Blizzard e permitem que o MSUF mostre borda, brilho e overlay de dissipação."
L["Blizzard renderer is still active, but this group is MSUF Custom because its Use Blizzard toggle is off. Other active Blizzard aura types can still show matching spells, so duplicates can appear."] = "O renderizador da Blizzard ainda esta ativo, mas este grupo e MSUF Custom porque o interruptor Usar Blizzard esta desligado. Outros tipos de aura Blizzard ativos ainda podem mostrar magias correspondentes, entao duplicatas podem aparecer."
