L["Checked categories hide MSUF custom debuff icons only. Blizzard-rendered debuffs bypass this list while Use Blizzard: Debuffs is enabled."] = "Categorias marcadas ocultam apenas icones de penalidades personalizados do MSUF. Penalidades renderizadas pela Blizzard ignoram esta lista enquanto Usar Blizzard: Penalidades estiver ativado."
