L["When enabled, WoW owns buff icons. MSUF hide categories and custom buff positioning do not filter Blizzard-rendered buffs, so Skyfury or Earth Shield can still appear."] = "Quando ativado, o WoW controla os icones de beneficios. As categorias ocultas do MSUF e o posicionamento personalizado de beneficios nao filtram beneficios renderizados pela Blizzard, entao Skyfury ou Earth Shield ainda podem aparecer."
L["When enabled, WoW owns debuff icons. MSUF hide categories and custom debuff positioning do not filter Blizzard-rendered debuffs."] = "Quando ativado, o WoW controla os icones de penalidades. As categorias ocultas do MSUF e o posicionamento personalizado de penalidades nao filtram penalidades renderizadas pela Blizzard."
L["When enabled, WoW owns defensive icons. MSUF custom positioning and styling apply only when this is off or the renderer is MSUF Custom."] = "Quando ativado, o WoW controla os icones defensivos. O posicionamento e estilo personalizados do MSUF so se aplicam quando isto esta desativado ou o renderizador e MSUF Custom."
