L["Profile-wide · follows the active Party, Raid, or Mythic Raid frame appearance"]="Para todo o perfil · segue a aparência dos quadros ativos de grupo, raide ou raide mítica"
L["Keep tanks and manually pinned group members in one stable strip without removing them from the normal Party or Raid frames."]="Mantenha tanques e membros fixados manualmente em uma faixa estável sem removê-los dos quadros normais de grupo ou raide."
L["Profile-wide layout · character-specific pins · available in parties and raids · inherits the active group-frame appearance and click-cast behavior."]="Layout para todo o perfil · fixações por personagem · disponível em grupos e raides · herda a aparência e o clique para lançar dos quadros de grupo ativos."
L["Waiting — enable Party frames first."]="Aguardando — ative primeiro os quadros de grupo."; L["Waiting — none of your saved players are in the current group."]="Aguardando — nenhum jogador salvo está no grupo atual."; L["Ready — pin a group member or include tanks automatically."]="Pronto — fixe um membro do grupo ou inclua tanques automaticamente."; L["Ready — join a party or raid to show Priority Frames."]="Pronto — entre em um grupo ou raide para mostrar os quadros prioritários."
L["Hover an MSUF Party, Raid, or Priority frame and press this key to pin or unpin that player."]="Passe o mouse sobre um quadro MSUF de grupo, raide ou prioritário e pressione esta tecla para fixar ou soltar o jogador."
L["No manual pins yet. While grouped, hover an MSUF Party, Raid, or Priority frame, then press your hotkey."]="Ainda não há fixações manuais. Em grupo, passe o mouse sobre um quadro MSUF de grupo, raide ou prioritário e pressione o atalho."
L["Use the hover hotkey above to add or remove players."]="Use o atalho acima para adicionar ou remover jogadores."; L["Saved · not grouped"]="Salvo · fora de grupo"; L["Saved · not in current group"]="Salvo · fora do grupo atual"; L["Saved · Party frames disabled"]="Salvo · quadros de grupo desativados"
L["Attach the strip to the active Party, Raid, or Mythic Raid container, or choose Free position and place it with Edit Mode."]="Anexe a faixa ao contêiner ativo de grupo, raide ou raide mítica, ou escolha Posição livre e posicione-a no modo de edição."
L["Right of group frames"]="À direita dos quadros de grupo"; L["Left of group frames"]="À esquerda dos quadros de grupo"; L["Above group frames"]="Acima dos quadros de grupo"; L["Below group frames"]="Abaixo dos quadros de grupo"; L["The strip follows the active Party, Raid, or Mythic Raid container automatically."]="A faixa segue automaticamente o contêiner ativo de grupo, raide ou raide mítica."
L["In party"]="Em grupo"; L["In raid"]="Em raide"; L["Not grouped"]="Fora de grupo"
L["Priority Frames keep automatic tanks and manually pinned group members in a stable extra strip. In a party they inherit Party Frames; in a raid they inherit the active Raid or Mythic Raid frames. The matching base group frames must be enabled. Open Group Frames > Priority to choose who appears, set a hover hotkey, and place the strip."]="Os quadros prioritários mantêm tanques automáticos e membros fixados em uma faixa extra estável. Em grupo, herdam os quadros de grupo; em raide, os quadros ativos de raide ou raide mítica. Os quadros-base correspondentes precisam estar ativos. Abra Quadros de grupo > Prioridade para escolher quem aparece, o atalho e a posição."
L["Free position uses the dedicated Priority Frames mover."]="A posição livre usa o movimentador próprio dos quadros prioritários."; L["How do Priority Frames work?"]="Como funcionam os quadros prioritários?"; L["Opens: Group Frames > Priority"]="Abre: Quadros de grupo > Prioridade"
L["Pin or unpin hovered group member"]="Fixar ou soltar o membro sob o mouse"; L["Priority Frames hotkey"]="Atalho dos quadros prioritários"; L["Left-click and press a key. Right-click, Backspace, or Delete clears it. Existing bindings are never replaced without confirmation."]="Clique com o botão esquerdo e pressione uma tecla. Botão direito, Backspace ou Delete limpam. Atalhos existentes nunca são substituídos sem confirmação."
