L["Health and Power use separate gradient colors. Choosing a color creates a custom Bars override for the selected scope."] = "Saúde e Energia usam cores gradientes separadas. A escolha de uma cor cria uma substituição de barras personalizada para o escopo selecionado."
L["UPGRADED TO MSUF %s"] = "ATUALIZADO PARA MSUF %s"
L["Your MSUF 6.0 highlights"] = "Seus destaques do MSUF 6.0"
L["Your current profile stays unchanged. Review %d new highlights and choose only what you want to configure."] = "Seu perfil atual permanece inalterado. Revise os novos destaques do %d e escolha apenas o que deseja configurar."
L["CURRENT PROFILE: %s - NO SETTINGS WILL BE CHANGED"] = "PERFIL ATUAL: %s - NENHUMA CONFIGURAÇÃO SERÁ ALTERADA"
L["Start %d-highlight tour"] = "Iniciar tour pelos destaques do %d"
L["Review the release highlights without changing your current profile."] = "Revise os destaques do lançamento sem alterar seu perfil atual."
L["Review exactly what you would skip before closing the tour."] = "Revise exatamente o que você pularia antes de encerrar o tour."
L["About two minutes. You can leave at any point and configure each area later."] = "Cerca de dois minutos. Você pode sair a qualquer momento e configurar cada área posteriormente."
L["Highlight %d of %d"] = "Destaque %d de %d"
L["WHY IT MATTERS"] = "POR QUE ISSO IMPORTA"
L["Finish tour"] = "Terminar passeio"
L["Next highlight"] = "Próximo destaque"
L["Mark this highlight as reviewed and continue."] = "Marque este destaque como revisado e continue."
L["Back"] = "Voltar"
L["Skip tour"] = "Pular passeio"
L["See the remaining highlights before deciding to skip them."] = "Veja os destaques restantes antes de decidir ignorá-los."
L["Skip %d remaining highlights?"] = "Ignorar os destaques restantes do %d?"
L["Your profile will stay safe, but you will leave these %d new configuration areas unexplored:"] = "Seu perfil permanecerá seguro, mas você deixará estas novas áreas de configuração do %d inexploradas:"
L["Show me the highlights"] = "Mostre-me os destaques"
L["Skip all %d and continue"] = "Ignore todos os %d e continue"
L["Skipping closes this release tour only. Every setting remains available in Menu2."] = "Skipping encerra apenas este tour de lançamento. Cada configuração permanece disponível no Menu2."
L["Custom Aura tracking on Unitframes"] = "Rastreamento de Aura personalizado em Unitframes"
L["Build up to three frame-specific Custom lanes on Player, Target, Focus and Boss, whitelist exact buff or debuff SpellIDs, and track your own DoTs on the Target frame with a curated per-class lane."] = "Crie até três faixas personalizadas em Jogador, Alvo, Foco e Chefe, adicione SpellIDs exatos de bônus ou penalidades e acompanhe seus próprios DoTs no Alvo com uma faixa por classe."
L["Your MSUF frames can act as focused WeakAura-style trackers with icons, timers, duration bars and full-frame tint, border, glow or pulse effects."] = "Seus quadros MSUF podem atuar como rastreadores focados no estilo WeakAura com ícones, temporizadores, barras de duração e efeitos de matiz, borda, brilho ou pulso de quadro completo."
L["three Custom Aura trackers per supported Unitframe, exact spell whitelists and full-frame effects"] = "três rastreadores de Aura personalizados por Unitframe compatível, listas de permissões de feitiços exatos e efeitos de quadro inteiro"
L["Build a Custom tracker"] = "Crie um rastreador personalizado"
L["Aura settings in the right place"] = "Configurações de aura no lugar certo"
L["Setup and individual styling now live in the matching Unitframe and Party/Raid menus. Appearance > Auras holds the expanded shared styles."] = "A configuração e o estilo individual agora ficam nos menus correspondentes de quadros de unidade e grupo/raide. Aparência > Auras contém os estilos compartilhados ampliados."
L["Configure each frame in context, then use Auras for shared icon shapes, borders, shadows, colors and spacing."] = "Configure cada quadro em seu contexto e use Auras para compartilhar formas de ícone, bordas, sombras, cores e espaçamento."
L["per-frame Aura controls and expanded shared styling in Appearance > Auras"] = "controles de aura por quadro e estilo compartilhado ampliado em Aparência > Auras"
L["Open shared Aura styles"] = "Abrir estilos de aura compartilhados"
L["Adaptive Party and Raid layouts"] = "Layouts adaptáveis para grupos e ataques"
L["Party, Raid and Mythic Raid gained adaptive layouts and scaling, per-lane aura filters and blacklists, a focused Dispel Overlay page, and per-group control over whether MSUF or Blizzard draws the frames."] = "Grupo, Raide e Raide mítica ganharam layouts adaptativos com escala, filtros e listas negras de auras por faixa, uma página dedicada de Dispel Overlay, e você decide por grupo se o MSUF ou a Blizzard desenha os quadros."
L["One group setup can follow you from a five-man into a raid, and you decide per lane which auras are allowed to show at all."] = "Uma única configuração de grupo acompanha você de uma masmorra de cinco até o raide, e você decide por faixa quais auras podem sequer aparecer."
L["adaptive group layouts and scaling, group aura filters and blacklists, the Dispel Overlay page and the group provider controls"] = "os layouts adaptativos e a escala, os filtros e listas negras de auras de grupo, a página Dispel Overlay e o controle de provedor por grupo"
L["Open Group Layout"] = "Layout de grupo aberto"
L["New health values and text formats"] = "Novos valores de saúde e formatos de texto"
L["Health text can show abbreviated or full values with more consistent formatting, and the new Maximum Health Loss overlay can mark lost maximum health on unit and group frames."] = "O texto de vida pode mostrar valores abreviados ou completos com formatação mais consistente, e a nova sobreposição de vida máxima perdida marca a vida máxima reduzida em quadros de unidade e de grupo."
L["You can choose compact readability or exact numbers without giving up the layout you already use."] = "Você pode escolher legibilidade compacta ou números exatos sem abrir mão do layout que já usa."
L["the new health abbreviations, full values, text formats and the Maximum Health Loss overlay"] = "as novas abreviações de vida, os valores completos, os formatos de texto e a sobreposição de vida máxima perdida"
L["Open HP Text Editor"] = "Abrir o editor de texto de vida"
L["More flexible class resources"] = "Recursos de aula mais flexíveis"
L["Class resources gained detached layouts, additional shapes and finer per-slot and full-state colors."] = "Os recursos de classe ganharam layouts separados, formas adicionais e cores mais refinadas por slot e em estado completo."
L["You can move class information where your eyes already are and make important states easier to read."] = "Você pode mover as informações da classe para onde seus olhos já estão e facilitar a leitura de estados importantes."
L["detached class resources, new shapes and per-state colors"] = "recursos de classe separados, novas formas e cores por estado"
L["Configure Class Resources"] = "Configurar recursos de classe"
L["Cast target text"] = "Transmitir texto de destino"
L["Target, Focus and Boss cast bars can now show who the current spell is targeting, with dedicated text styling."] = "As barras de lançamento de Alvo, Foco e Chefe agora podem mostrar quem é o alvo do feitiço atual, com estilo de texto dedicado."
L["You can identify the destination of an important cast without shifting attention away from the cast bar."] = "Você pode identificar o destino de um elenco importante sem desviar a atenção da barra de elenco."
L["cast-target names and their text styling on Target, Focus and Boss frames"] = "nomes de destinos lançados e seu estilo de texto nos quadros Target, Focus e Boss"
L["Open Target Cast Bar"] = "Abrir barra de transmissão de destino"
L["Review or skip the release highlights on the Dashboard before using first-load actions."] = "Revise ou ignore os destaques da versão no Painel antes de usar ações de primeiro carregamento."
L["Priority Frames for the units that matter"] = "Quadros prioritários para as unidades que importam"
L["Pin up to five group members by hand, or let MSUF pick the tanks automatically, and give them their own strip that never reshuffles mid-fight."] = "Fixe até cinco membros do grupo à mão, ou deixe o MSUF escolher os tanques automaticamente, e dê a eles uma faixa própria que nunca se reorganiza no meio da luta."
L["The people you have to watch keep one fixed spot on screen, with the Party or Raid look and click-casting they already had."] = "As pessoas que você precisa acompanhar mantêm um lugar fixo na tela, com a aparência de grupo ou raide e a conjuração por clique que já tinham."
L["Priority Frames, manual and automatic pinning, and their own placement"] = "os quadros prioritários, a fixação manual e automática e o posicionamento próprio deles"
L["Set up Priority Frames"] = "Configurar quadros prioritários"
L["One Colors page with click-to-paint"] = "Uma página de cores com pintura por clique"
L["Every color moved onto one page, grouped into Player & Target, Party & Raid, Castbar, Aura, Power and Class Resource workspaces with their own live preview."] = "Todas as cores foram para uma única página, agrupadas em áreas de Jogador e Alvo, Grupo e Raide, Barra de Conjuração, Auras, Energia e Recursos de Classe, cada uma com sua prévia ao vivo."
L["You can click the element in the preview to paint it instead of hunting for the matching swatch, and reuse any color from a recent or saved palette."] = "Você clica no elemento na prévia para pintá-lo em vez de procurar a amostra certa, e reaproveita qualquer cor de uma paleta recente ou salva."
L["the rebuilt Colors page, click-to-paint previews, palettes and the new color picker"] = "a página de cores reconstruída, as prévias de pintar por clique, as paletas e o novo seletor de cores"
L["Open the Colors page"] = "Abrir a página de cores"
L["One 0-30 layer scale for everything"] = "Uma escala de camadas 0-30 para tudo"
L["Text, status icons, auras, borders, bar outlines, group indicators and class resources all order themselves on one shared 0-30 layer scale."] = "Textos, ícones de status, auras, bordas, contornos de barra, indicadores de grupo e recursos de classe se organizam em uma única escala de camadas 0-30."
L["You decide exactly what draws in front of what, and the Layer Overview beside any layer slider shows the whole stack at once."] = "Você decide exatamente o que é desenhado na frente do quê, e a visão geral de camadas ao lado de qualquer controle de camada mostra a pilha inteira de uma vez."
L["the addon-wide 0-30 layer scale and the Layer Overview"] = "a escala de camadas 0-30 válida para todo o addon e a visão geral de camadas"
L["MSUF Edit Mode, rebuilt"] = "O Modo de Edição do MSUF, reconstruído"
L["Edit Mode gained a dockable toolbar, redesigned quick popups on every frame, and Undo and Redo that behave the same there as in the menu."] = "O Modo de Edição ganhou uma barra de ferramentas acoplável, menus rápidos redesenhados em cada quadro e Desfazer e Refazer que funcionam ali como no menu."
L["You can move, size and copy frames directly on screen and step back out of any mistake without reopening the menu."] = "Você move, redimensiona e copia quadros direto na tela e volta atrás de qualquer erro sem reabrir o menu."
L["the rebuilt Edit Mode toolbar, its quick popups and shared Undo and Redo"] = "a nova barra de ferramentas do Modo de Edição, seus menus rápidos e o Desfazer/Refazer compartilhado"
L["Start Edit Mode"] = "Iniciar o Modo de Edição"
L["Spell Indicators on Group Frames"] = "Spell Indicators nos quadros de grupo"
L["Track chosen buffs on Party and Raid frames as icon, square, bar or number indicators, with custom spell lists and corner indicators."] = "Acompanhe bônus escolhidos nos quadros de grupo e raide como ícone, quadrado, barra ou número, com listas de feitiços personalizadas e indicadores de canto."
L["You can see missing or expiring externals and key buffs directly on the frames, with expiring icon glows, health-bar highlights and full-frame effects."] = "Você vê externals faltando ou expirando e bônus importantes direto nos quadros, com brilho de expiração, destaque da barra de vida e efeitos no quadro inteiro."
L["Spell Indicators with custom aura lists, corner indicators and expiring-effect warnings"] = "os Spell Indicators com listas de auras personalizadas, indicadores de canto e avisos de expiração"
L["Open Spell Indicators"] = "Abrir Spell Indicators"
L["Fill Direction for Health and Power"] = "Direção de preenchimento de Vida e Poder"
L["Every Unit Frame can fill its Health and Power left to right, right to left, bottom to top or top to bottom."] = "Cada quadro de unidade pode preencher Vida e Poder da esquerda para a direita, direita para a esquerda, de baixo para cima ou de cima para baixo."
L["Vertical and mirrored bar layouts become a per-frame choice - something no other unit frame addon currently offers."] = "Layouts verticais ou espelhados viram uma escolha por quadro - algo que nenhum outro addon de unit frames oferece atualmente."
L["the per-frame Fill Direction control for Health and Power bars"] = "o controle de direção de preenchimento por quadro para as barras de Vida e Poder"
L["Choose a Fill Direction"] = "Escolher a direção de preenchimento"
L["Portraits: attached, detached or overlay"] = "Retratos: anexado, solto ou overlay"
L["Portraits can stay attached, float freely or render as an overlay inside the health bar, with independent size, nine-point anchoring, opacity and pannable zoom."] = "Os retratos podem ficar anexados, flutuar livres ou ser desenhados como overlay dentro da barra de vida, com tamanho independente, ancoragem em nove pontos, opacidade e zoom deslocável."
L["Rectangular and watermark-style portraits become possible, and Relief rings plus shape-following borders frame Square, Circle, Rounded and Diamond portraits."] = "Retratos retangulares ou em marca-d'água se tornam possíveis, e os anéis Relief mais as bordas que seguem a forma emolduram retratos quadrados, circulares, arredondados e de diamante."
L["the new portrait placement modes, Relief rings and shape-following portrait borders"] = "os novos modos de posicionamento de retrato, os anéis Relief e as bordas que seguem a forma"
L["Open Portrait settings"] = "Abrir ajustes de retrato"
L["Status icon packs"] = "Pacotes de ícones de status"
L["Role, leader, raid marker, ready check and every other status icon can switch between twelve bundled styles or your own custom icons, per indicator."] = "Função, líder, marcador de raide, checagem de prontidão e todo outro ícone de status podem alternar entre doze estilos incluídos ou seus próprios ícones, por indicador."
L["Status icons can finally match your UI style instead of always using Blizzard art, and external packs can register through SharedMedia."] = "Os ícones de status finalmente podem combinar com a sua interface em vez da arte da Blizzard, e pacotes externos podem se registrar via SharedMedia."
L["the twelve status icon styles and per-indicator custom icons"] = "os doze estilos de ícones de status e os ícones personalizados por indicador"
L["Pick an icon style"] = "Escolher um estilo de ícones"
L["Old"] = "Velho"
L["MSUF menu font"] = "Fonte do menu MSUF"
L["Blizzard default"] = "Padrão da nevasca"
L["AaBbCc 12345 - MSUF Menu"] = "AaBbCc 12345 - Menu MSUF"
L["Preview Controls"] = "Controles de visualização"
L["Preview controls"] = "Controles de visualização"
L["Drag handles to move."] = "Arraste as alças para mover."
L["Double-click/settings: open options."] = "Clique duas vezes em /settings: opções abertas."
L["Right-click: quick actions."] = "Clique com o botão direito: ações rápidas."
L["Arrows nudge. Shift=5, Ctrl=10."] = "As setas cutucam. Shift=5, Ctrl=10."
L["Ctrl+wheel zooms. Ctrl+drag pans. Fit recenters."] = "Ctrl+roda de zoom. Ctrl+arrastar panelas. Ajuste recentradores."
