L["Skipping frame placement leaves whole-frame movement, snapping, nudging and safe exit behavior unexplained."] = "Pular a colocação do quadro deixa o movimento de todo o quadro, o encaixe, o empurrão e o comportamento de saída segura inexplicáveis."
L["Skipping the Player frame leaves its layout, text, indicators and aura options unreviewed."] = "Ignorar o quadro do Player deixa seu layout, texto, indicadores e opções de aura sem revisão."
