L["Skipping Boss frames leaves their shared layout, text, indicators and aura options unreviewed."] = "Ignorar os quadros do Boss deixa seu layout compartilhado, texto, indicadores e opções de aura sem revisão."
L["Skipping group layout leaves frame size, growth, sorting, scaling and anchoring unreviewed."] = "Ignorar o layout do grupo deixa o tamanho do quadro, o crescimento, a classificação, o dimensionamento e a ancoragem sem revisão."
L["Skipping group bars leaves health, power, text, range and dispel presentation unreviewed."] = "Ignorar as barras de grupo deixa a apresentação de saúde, poder, texto, alcance e dissipação sem revisão."
L["Skipping group auras leaves group buff, debuff and spell-indicator behavior unreviewed."] = "Ignorar auras de grupo deixa o comportamento de buff, debuff e indicador de feitiço do grupo sem revisão."
L["Skipping Bars leaves global textures, absorbs, outlines, highlights and power behavior unreviewed."] = "Pular barras deixa texturas globais, absorventes, contornos, destaques e comportamento de poder sem revisão."
L["Skipping Cast Bars leaves cast appearance, text, empowered casts and interrupt cues unreviewed."] = "Ignorar as barras de transmissão deixa a aparência do elenco, o texto, os lançamentos fortalecidos e as dicas de interrupção sem revisão."
L["Skipping Colors leaves frame, power, aura, class, text and castbar colors unreviewed."] = "Ignorar cores deixa as cores de quadro, poder, aura, classe, texto e barra de cast sem revisão."
L["Skipping Fonts leaves the global font, text styling, colors and name shortening unreviewed."] = "Ignorar fontes deixa a fonte global, o estilo do texto, as cores e o encurtamento do nome sem revisão."
L["Skipping Aura styling leaves buff/debuff size, cooldown, stacks, duration bars and ordering unreviewed."] = "Ignorar o estilo da Aura deixa o tamanho, o tempo de espera, as acúmulos, as barras de duração e a ordem do buff/debuff sem revisão."
L["Skipping Miscellaneous leaves language, menu behavior, startup, tooltips and Blizzard-frame integration unreviewed."] = "Ignorar Diversos deixa o idioma, o comportamento do menu, a inicialização, as dicas de ferramentas e a integração do quadro da Blizzard sem revisão."
L["Skipping Class Resources leaves class layout, behavior, style, visibility and alternative power displays unreviewed."] = "Ignorar os recursos da aula deixa o layout, o comportamento, o estilo, a visibilidade e as exibições alternativas de poder da aula sem revisão."
L["Skipping Gameplay leaves combat timers, state behavior, class toggles and the combat crosshair unreviewed."] = "Pular a jogabilidade deixa os cronômetros de combate, o comportamento do estado, as alternâncias de classe e a mira de combate sem revisão."
L["Skipping Profiles leaves profile management, specialization assignment and export/import backup unreviewed."] = "Ignorar perfis deixa o gerenciamento de perfis, atribuição de especialização e backup de exportação/import sem revisão."
L["Skipping the final review hides the summary, but does not change any setting."] = "Ignorar a revisão final oculta o resumo, mas não altera nenhuma configuração."
