L["Spell-specific channel tick markers"] = "Marcadores de tick de canal específicos de feitiço"
L["Runs a short castbar for the global cooldown whenever an instant spell triggers it.\n\nThe fill and time text are driven natively by the client from the real (haste-scaled) GCD duration - no per-frame addon work while the bar runs. A real cast, channel or empower always takes priority."] = "Mostra uma barra de lançamento curta para a recarga global quando um feitiço instantâneo a aciona.\n\nO preenchimento e o texto de tempo são controlados nativamente pelo cliente com base na duração real do GCD (ajustada pela aceleração) - nenhum trabalho do addon por quadro enquanto a barra está ativa. Um lançamento real, uma canalização ou um feitiço potencializado sempre tem prioridade."
L["Shows tick separators on the Player castbar while channeling.\n\nSupported spells use their actual tick count, including supported talent and channel-duration changes. Unsupported channels keep five evenly spaced fallback lines. Custom channel tick settings override the automatic layout.\n\nThe markers are event-driven and add no recurring channel polling."] = "Mostra separadores de ticks na barra de lançamento do jogador durante a canalização.\n\nOs feitiços suportados usam sua contagem real de ticks, incluindo talentos suportados e alterações na duração do canal. Canais não suportados mantêm cinco linhas alternativas espaçadas uniformemente. As configurações personalizadas de tick de canal substituem o layout automático.\n\nOs marcadores são orientados por eventos e não adicionam pesquisas recorrentes de canal."
L["Class Color (Reaction fallback)"] = "Cor da classe (reação substituta)"
L["Ready color (kick available)"] = "Cor pronta (chute disponível)"
L["Not ready color (kick on cooldown)"] = "Cor não pronta (ativar no tempo de espera)"
L["PvP Flag (War Mode/PvP)"] = "Bandeira PvP (modo de guerra/PvP)"
L["Abbreviate HP values (K/M)"] = "Valores abreviados de HP (K/M)"
L["For specializations that use mana alongside another resource."] = "Para especializações que usam mana junto com outro recurso."
L["Smooths resource changes. Runes, Essence recharge, and timers keep their own animation."] = "Suaviza as alterações de recursos. Runas, recarga de Essência e temporizadores mantêm sua própria animação."
L["Exact Spell IDs are used when Blizzard exposes them."] = "IDs de feitiço exatos são usados quando a Blizzard os expõe."
L["Reverses only the swipe overlay. Icon size and position stay unchanged."] = "Inverte apenas a sobreposição de deslizamento. O tamanho e a posição do ícone permanecem inalterados."
L["Only relevant sorting methods are shown for buffs and debuffs."] = "Apenas métodos de classificação relevantes são mostrados para buffs e debuffs."
L["Reversed flips the complete priority order."] = "Invertido inverte a ordem de prioridade completa."
