L["Open Bars"] = "Barras abertas"
L["Open Colors > Bar Gradient Colors for separate Health and Power gradient colors in the selected Bars scope."] = "Abra Cores > Cores de gradiente de barra para cores de gradiente de saúde e energia separadas no escopo de barras selecionado."
L["Open Colors > Group Frame Colors for shared Party, Raid and Mythic Raid colors."] = "Abra Cores > Cores de quadro de grupo para cores compartilhadas de Party, Raid e Mythic Raid."
L["Open Edit Mode and move Party Frames"] = "Abra o modo de edição e mova os quadros da festa"
L["Open Group Frames > Auras for Buff/Debuff filters, lists, visibility, and layout. For text, cooldowns, stacks, and duration bars use Appearance > Auras and select Party or Raid scope."] = "Abra Group Frames > Auras para filtros, listas, visibilidade e layout de Buff/Debuff. Para texto, tempos de espera, acúmulos e barras de duração, use Aparência > Auras e selecione o escopo Grupo ou Raide."
L["Open Group Frames > Layout. Text, Resource Bar, and Range Fade are arranged beside Frame Basics and Transparency. Dispel Overlay and Debuff Stripe are on the Dispel Overlay page. Heal prediction is in Global Style > Bars > Absorb Display."] = "Abra Quadros de grupo > Layout. Texto, Barra de recursos e Esmaecimento de intervalo estão organizados ao lado de Noções básicas de quadro e Transparência. Dispel Overlay e Debuff Stripe estão na página Dispel Overlay. A previsão de cura está em Estilo Global > Barras > Exibição de Absorção."
L["Open it and choose a different value."] = "Abra-o e escolha um valor diferente."
L["Open the affected UnitFrame > Auras > Debuffs and enable the native Dispellable rule. For Party/Raid use Group Frames > Auras > Debuffs."] = "Abra UnitFrame> Auras> Debuffs afetados e habilite a regra Dispellable nativa. Para Party/Raid use Group Frames > Auras > Debuffs."
L["Open the affected UnitFrame > Auras > Debuffs and use its frame-specific SpellID blacklist. Group exclusions live directly in Group Frames > Auras > Debuffs."] = "Abra UnitFrame> Auras> Debuffs afetados e use sua lista negra SpellID específica do quadro. As exclusões de grupo ficam diretamente em Group Frames > Auras > Debuffs."
L["Open the affected UnitFrame > Auras and choose Buffs or Debuffs. Check its frame-specific Blizzard filters, blacklist, enabled state, and icon cap. For Party/Raid use Group Frames > Auras."] = "Abra o UnitFrame> Auras afetado e escolha Buffs ou Debuffs. Verifique os filtros Blizzard específicos do quadro, lista negra, estado ativado e limite de ícone. Para Party/Raid use Group Frames > Auras."
L["Open the affected UnitFrame > Auras for visibility, layout, filters, and blacklists. Use Appearance > Auras for scope-aware cooldown, stack, duration-bar, and icon styling."] = "Abra o UnitFrame> Auras afetado para visibilidade, layout, filtros e listas negras. Use Aparência> Auras para resfriamento, pilha, barra de duração e estilo de ícone com reconhecimento de escopo."
L["Open the frame and expand Auras. Buffs and Debuffs contain their own Blizzard filters and blacklists; Custom 1-3 contains its own whitelist. There is no separate Filter tab."] = "Abra o quadro e expanda Auras. Buffs e Debuffs contêm seus próprios filtros e listas negras da Blizzard; Custom 1-3 contém sua própria lista de permissões. Não há uma guia Filtro separada."
