L["Unit frame status icons are on each unit page. Group Spell Indicators are in Group Frames > Auras; group status and corner indicators are in Group Frames > Status & Indicators."] = "Os ícones de status da estrutura da unidade estão em cada página da unidade. Os Indicadores de Feitiços de Grupo estão em Quadros de Grupo > Auras; o status do grupo e os indicadores de canto estão em Quadros de grupo > Status e indicadores."
