-- MSUF FULL CORE MENU SOURCE INVENTORY 2
-- Generated missing non-Assistant core keys for ptBR.
L["+"] = "+"
L["Can Priority Frames automatically select healers, DPS, classes, or specs?"] = "Os Priority Frames podem selecionar automaticamente healers, DPS, classes ou especificações?"
L["Can Priority Frames automatically show Augmentation Evokers?"] = "Os quadros prioritários podem mostrar automaticamente evocadores de aumento?"
L["Can Priority Frames show my co-tank?"] = "Os Priority Frames podem mostrar meu co-tanque?"
L["Can Priority Frames update during combat?"] = "Os quadros prioritários podem ser atualizados durante o combate?"
L["Check that Priority Frames are enabled, you are grouped, and the matching base Party or Raid frames are enabled. Confirm that an assigned tank or manually pinned player is currently in the group and Visible slots is not full. Saved absent players create no empty placeholders, and protected roster changes made in combat finish after combat ends."] = "Verifique se os quadros prioritários estão habilitados, se você está agrupado e se os quadros básicos de grupo ou ataque correspondentes estão habilitados. Confirme se um tanque atribuído ou jogador fixado manualmente está atualmente no grupo e se os slots visíveis não estão cheios. Jogadores ausentes salvos não criam espaços reservados vazios e protegem as alterações na escalação feitas no final do combate após o término do combate."
L["Class Color and Health Gradient are runtime colors, not a single editable swatch."] = "Class Color e Health Gradient são cores de tempo de execução, não uma única amostra editável."
L["Cleave Training Dummy"] = "Cleave Boneco de Treinamento"
L["Custom 1-3 are always stored per frame. Icon styling and Full-Frame effects here only change "] = "Os personalizados 1-3 são sempre armazenados por quadro. O estilo dos ícones e os efeitos Full-Frame aqui apenas mudam"
L["Disabled or whitelist empty"] = "Desativado ou lista de permissões vazia"
L["Do Priority Frame pins persist, and what order do they use?"] = "Os pinos do Quadro Prioritário persistem e que ordem eles usam?"
L["Do Priority Frames inherit click casting and appearance?"] = "Os quadros prioritários herdam a projeção e a aparência do clique?"
L["Do Priority Frames use polling?"] = "Os quadros prioritários usam votação?"
L["Do Priority Frames work in parties and dungeons?"] = "Os Priority Frames funcionam em grupos e masmorras?"
L["Enter text"] = "Insira o texto"
L["Existing Priority frames remain usable in combat, but WoW protects secure group-frame membership and layout changes. Any pin, roster, slot, or placement change that needs a secure refresh is applied after combat ends. Change the Priority Frames keybinding out of combat."] = "Os frames Prioritários existentes permanecem utilizáveis em combate, mas o WoW protege a adesão segura aos frames do grupo e as alterações de layout. Qualquer alteração de pin, escalação, slot ou posicionamento que precise de uma atualização segura será aplicada após o término do combate. Altere o atalho de teclado dos Quadros Prioritários fora de combate."
L["Follows Unitframe Global Coloring. The swatch previews the current global bar color."] = "Segue a coloração global Unitframe. A amostra visualiza a cor atual da barra global."
L["For Priority Frames, layout is profile-wide, while pins are character-specific. Visible slots can be set from one to five. Automatic tanks fill first, followed by manual pins in saved order; duplicate selections appear once. A saved player who is absent waits until that player rejoins the current group."] = "Para quadros prioritários, o layout abrange todo o perfil, enquanto os pinos são específicos do caractere. Os slots visíveis podem ser definidos de um a cinco. Os tanques automáticos são preenchidos primeiro, seguidos pelos pinos manuais na ordem salva; seleções duplicadas aparecem uma vez. Um jogador salvo que está ausente espera até que esse jogador volte ao grupo atual."
L["Frames"] = "Molduras"
L["How do I pin or unpin a player in Priority Frames?"] = "Como faço para fixar ou desafixar um jogador em quadros prioritários?"
L["How do I position Priority Frames?"] = "Como posiciono os quadros prioritários?"
L["How should an Augmentation Evoker use Priority Frames?"] = "Como um Augmentation Evoker deve usar quadros prioritários?"
L["Inherited: this scope follows Shared aura style. Enable custom aura style only when this scope needs different text, swipe, border, or timer settings."] = "Herdado: este escopo segue o estilo de aura compartilhada. Ative o estilo de aura personalizado somente quando esse escopo precisar de configurações diferentes de texto, deslizamento, borda ou temporizador."
L["Leave text"] = "Deixe o texto"
L["Live "] = "Ao vivo"
L["Live preview is unavailable for this container. Sample mode remains available."] = "A visualização ao vivo não está disponível para este contêiner. O modo de amostra permanece disponível."
L["Live preview updates after combat. Sample mode remains available."] = "Atualizações de visualização ao vivo após o combate. O modo de amostra permanece disponível."
L["Manually pin the teammates you want to keep visible for monitoring or click-casting. Priority Frames does not decide who should receive Prescience or Ebon Might. Configure Group Frames > Auras > Spell Indicators if you want inherited Priority frames to show Prescience, Ebon Might, Shifting Sands, Blistering Scales, or other configured effects."] = "Fixe manualmente os colegas de equipe que você deseja manter visíveis para monitoramento ou transmissão de cliques. Priority Frames não decide quem deve receber Presciência ou Ebon Might. Configure Molduras de Grupo > Auras > Indicadores de Feitiço se quiser que molduras de Prioridade herdadas mostrem Presciência, Poder de Ébano, Areias Moventes, Escamas Bolhas ou outros efeitos configurados."
L["Mouseover highlight"] = "Destaque ao passar o mouse"
L["Native · "] = "Nativo ·"
L["No continuous polling ticker or OnUpdate loop is used for Priority selection. It resolves the roster when configuration, pins, group state, or relevant unit identity changes require a refresh. Automatic selection reads WoW's assigned TANK role and does not inspect every group member's specialization in the background."] = "Nenhum ticker de pesquisa contínua ou loop OnUpdate é usado para seleção de prioridade. Ele resolve a lista quando a configuração, os pinos, o estado do grupo ou alterações relevantes na identidade da unidade exigem uma atualização. A seleção automática lê a função TANK atribuída ao WoW e não inspeciona a especialização de cada membro do grupo em segundo plano."
L["No live "] = "Não ao vivo"
L["No live member"] = "Nenhum membro ativo"
L["No matching aura active"] = "Nenhuma aura correspondente ativa"
L["No. Automatic selection currently uses only WoW's assigned TANK role. Healers, DPS, classes, specializations, and support targets must be pinned manually with the hover hotkey. This avoids background inspection or polling and keeps the selection deterministic."] = "Não. A seleção automática atualmente usa apenas a função TANK atribuída ao WoW. Curandeiros, DPS, classes, especializações e alvos de suporte devem ser fixados manualmente com a tecla de atalho instantânea. Isso evita inspeção ou sondagem em segundo plano e mantém a seleção determinística."
L["Open Group Frames > Priority > Placement. Attach the strip to the right, left, top, or bottom of the active Party/Raid container, or choose Free position and use the dedicated Priority Frames mover in Edit Mode. The same page controls growth, spacing, attachment gap, and alignment offset."] = "Abra Quadros de grupo > Prioridade > Posicionamento. Anexe a faixa à direita, esquerda, superior ou inferior do contêiner Party/Raid ativo ou escolha a posição Livre e use o movedor de quadros prioritários dedicado no modo de edição. A mesma página controla o crescimento, o espaçamento, o espaço de anexo e o deslocamento de alinhamento."
L["Override active: this scope keeps its own aura style. Shared style changes will not replace it until the override is reset."] = "Substituição ativa: este escopo mantém seu próprio estilo de aura. As alterações de estilo compartilhadas não irão substituí-lo até que a substituição seja redefinida."
L["Priority Frames does not automatically detect other players' specializations. Automatic selection currently supports WoW-assigned tanks only. Pin an Augmentation Evoker manually with the hover hotkey; Priority Frames does not choose ideal Prescience or Ebon Might targets."] = "Priority Frames não detecta automaticamente as especializações de outros jogadores. A seleção automática atualmente suporta apenas tanques atribuídos ao WoW. Fixe um Augmentation Evoker manualmente com a tecla de atalho flutuante; Priority Frames não escolhe alvos ideais de Prescience ou Ebon Might."
L["Priority Frames duplicate automatic tanks and manually pinned current group members into a stable extra strip without removing them from the normal Party or Raid frames. In a party they inherit Party Frames; in a raid they inherit the active Raid or Mythic Raid frames. They work in parties, raids, and Mythic raids, inherit the active group-frame click-cast behavior, and require the matching base group frames to be enabled."] = "Os quadros prioritários duplicam os tanques automáticos e fixam manualmente os membros atuais do grupo em uma faixa extra estável sem removê-los dos quadros normais do grupo ou do ataque. Em um grupo eles herdam Party Frames; em uma invasão, eles herdam os quadros Raid ou Mythic Raid ativos. Eles funcionam em grupos, ataques e ataques míticos, herdam o comportamento de clique-cast do quadro de grupo ativo e exigem que os quadros de grupo base correspondentes sejam habilitados."
L["Shared aura style is the baseline for unit-frame aura text, swipe, border, and timer settings. Party and Raid are group-frame style scopes with their own settings."] = "O estilo de aura compartilhado é a base para texto de aura de quadro unitário, deslizar, borda e configurações de temporizador. Party e Raid são escopos de estilo de grupo com suas próprias configurações."
L["Textures are shared except Party/Raid group-frame overrides. Gradients can be customized per unit or group scope."] = "As texturas são compartilhadas, exceto substituições de quadros de grupo Party/Raid. Os gradientes podem ser personalizados por escopo de unidade ou grupo."
L["This group scope can use custom textures and gradients. Raid also applies to Mythic Raid."] = "Este escopo de grupo pode usar texturas e gradientes personalizados. Raid também se aplica ao Mythic Raid."
L["This scope can use custom gradients and bar settings. Textures still follow Shared."] = "Este escopo pode usar gradientes personalizados e configurações de barra. As texturas ainda seguem o Compartilhado."
L["This scope follows Shared bar settings. Turn on custom settings here when this scope needs different gradients or bar settings."] = "Este escopo segue as configurações da barra compartilhada. Ative as configurações personalizadas aqui quando este osciloscópio precisar de diferentes gradientes ou configurações de barra."
L["Updates after combat"] = "Atualizações após o combate"
L["Where can I request a Priority Frames feature?"] = "Onde posso solicitar um recurso de Quadros Prioritários?"
L["While grouped, set the hover hotkey on Group Frames > Priority. Hover an MSUF Party, Raid, or Priority frame and press the Priority Frames hotkey to pin or unpin that player. Players cannot be added by typing a name or while outside the current group; a saved absent pin waits and reappears when that player rejoins."] = "Enquanto estiver agrupado, defina a tecla de atalho flutuante em Group Frames > Priority. Passe o mouse sobre um quadro MSUF Party, Raid ou Priority e pressione a tecla de atalho Priority Frames para fixar ou desafixar esse jogador. Os jogadores não podem ser adicionados digitando um nome ou fora do grupo atual; um pin ausente salvo espera e reaparece quando o jogador volta."
L["Why are my Priority Frames empty or missing?"] = "Por que meus quadros prioritários estão vazios ou ausentes?"
L["Yes. Include tanks automatically selects current group members whose WoW-assigned role is TANK, normally including both you and your co-tank. To show only your co-tank, disable automatic tanks and manually pin the other tank. If WoW has not assigned that player the TANK role, manual pinning is the fallback."] = "Sim. Incluir tanques seleciona automaticamente os membros atuais do grupo cuja função atribuída no WoW é TANQUE, normalmente incluindo você e seu co-tanque. Para mostrar apenas o seu co-tanque, desative os tanques automáticos e fixe manualmente o outro tanque. Se o WoW não atribuiu a função TANQUE a esse jogador, a fixação manual é a solução alternativa."
L["Yes. Priority Frames inherit the active Party, Raid, or Mythic Raid frame appearance, including configured bars, text, auras, status indicators, and spell indicators. They use the same MSUF click-casting registration and unit behavior, so existing click-cast bindings also work on the duplicated frames."] = "Sim. Os quadros prioritários herdam a aparência ativa do quadro Party, Raid ou Mythic Raid, incluindo barras configuradas, texto, auras, indicadores de status e indicadores de feitiço. Eles usam o mesmo registro de conversão de clique do MSUF e comportamento de unidade, portanto, as ligações de conversão de clique existentes também funcionam nos quadros duplicados."
L["Yes. Priority Frames work in parties, raids, and Mythic raids. In a party or dungeon they inherit Party Frames; in a raid they inherit the active Raid or Mythic Raid setup. They do not create a solo strip, and the matching base Party or Raid frames must be enabled."] = "Sim. Os quadros prioritários funcionam em grupos, ataques e ataques míticos. Em um grupo ou masmorra eles herdam Party Frames; em uma invasão, eles herdam a configuração ativa da Raid ou Mythic Raid. Eles não criam uma faixa solo e os quadros básicos de Party ou Raid correspondentes devem estar habilitados."
