L["Castbar text follows the shared Fonts settings until this text gets its own color."] = "O texto da barra de conjuração segue as configurações de fonte compartilhadas até receber a própria cor."
L["Font style follows the Fonts menu for this frame; the color can be set per indicator."] = "O estilo da fonte segue o menu Fontes deste quadro; a cor pode ser definida por indicador."
L["Each castbar text can override the shared castbar text color. Target text exists on Target and Focus only."] = "Cada texto da barra de conjuração pode substituir a cor compartilhada. O texto de alvo existe apenas em Alvo e Foco."
L["Color for a single text indicator on one frame. Unset indicators follow that frame's font color."] = "Cor de um único indicador de texto em um quadro. Sem cor própria, o indicador segue a fonte do quadro."
