L["Shared icon shape"] = "Forma de ícone compartilhada"
L["Visibility modes apply only to unit and group frames. Aura tooltips use their own Show Tooltip switches; even Never does not override them. Auras only reuse the selected Blizzard/MSUF look and cursor placement."] = "Os modos de visibilidade se aplicam apenas aos quadros de unidade e de grupo. As dicas de auras usam seus próprios interruptores Mostrar dica; nem mesmo Nunca as substitui. As auras apenas reutilizam a aparência Blizzard/MSUF selecionada e a posição do cursor."
L["Applies to the entire castbar: bar, icon, all text, effects, and border. All MSUF elements share this 0-30 order; every part of layer 30 draws above every part of layer 29."] = "Aplica-se a toda a barra de lançamento: barra, ícone, todos os textos, efeitos e borda. Todos os elementos do MSUF compartilham esta ordem 0-30; cada parte da camada 30 é desenhada acima de cada parte da camada 29."
L["Display: "] = "Exibição: "
