--- Blizzard Raid Manager visibility (Group Frames > Layout > Frame Basics)
L["Always hidden"] = "Sempre oculto"
L["Blizzard Raid Manager"] = "Gerenciador de Raide da Blizzard"
L["Blizzard's tab at the left screen edge with ready check, raid markers, and role filters. One shared frame, so this setting is the same for Party, Raid, and Mythic Raid."] = "A aba da Blizzard na borda esquerda da tela com verificação de prontidão, marcadores de raide e filtros de função. É um único quadro compartilhado, então esta opção é a mesma para Grupo, Raide e Raide Mítica."
L["Fades the Raid Manager out until the mouse touches it. Ready check, raid markers, and role filters stay reachable, and an expanded panel stays visible until you collapse it again."] = "Esmaece o Gerenciador de Raide até o mouse tocá-lo. Verificação de prontidão, marcadores de raide e filtros de função continuam acessíveis, e um painel expandido permanece visível até você recolhê-lo novamente."
L["Keeps the Raid Manager invisible and click-through at all times. Switch back to reach its buttons again."] = "Mantém o Gerenciador de Raide invisível e sem capturar cliques o tempo todo. Volte a opção para alcançar os botões dele."
L["Show on mouseover"] = "Mostrar ao passar o mouse"
L["Automatic"] = "Automático"
L["Always visible"] = "Sempre visível"
L["Hides the Raid Manager while MSUF provides the live group frames, and leaves it to WoW otherwise. This is how MSUF has always behaved."] = "Oculta o Gerenciador de Raide enquanto o MSUF fornece os quadros de grupo ativos e, caso contrário, deixa por conta do WoW. O MSUF sempre se comportou assim."
L["Keeps the Raid Manager reachable even with MSUF group frames on. Use this when you still want its ready check, raid markers, and role filters."] = "Mantém o Gerenciador de Raide acessível mesmo com os quadros de grupo do MSUF ativos. Use isto se ainda quiser a verificação de prontidão, os marcadores de raide e os filtros de função."
L["Shared by Party, Raid, and Mythic Raid. Automatic keeps the tab hidden while MSUF provides the group frames."] = "Compartilhado por Grupo, Raide e Raide Mítica. Automático mantém a aba oculta enquanto o MSUF fornece os quadros de grupo."
L["MSUF detected %s."] = "MSUF detected %s."
L["Would you like MSUF to anchor the global Unit Frame layout to Essential Cooldown Manager?"] = "Would you like MSUF to anchor the global Unit Frame layout to Essential Cooldown Manager?"
L["Nothing will move unless you confirm again in the next step. You can change this later in MSUF Edit Mode."] = "Nothing will move unless you confirm again in the next step. You can change this later in MSUF Edit Mode."
L["Nothing will move unless you confirm again in the next step. If you choose Keep independent, you can enable CDM anchoring at any time in MSUF Edit Mode or under Unit > Anchoring in the MSUF menu."] = "Nothing will move unless you confirm again in the next step. If you choose Keep independent, you can enable CDM anchoring at any time in MSUF Edit Mode or under Unit > Anchoring in the MSUF menu."
L["Second confirmation for %s."] = "Second confirmation for %s."
L["MSUF will now anchor the global Unit Frame layout to Essential Cooldown Manager."] = "MSUF will now anchor the global Unit Frame layout to Essential Cooldown Manager."
L["Confirm only if you want the whole Unit Frame layout to move with your cooldowns."] = "Confirm only if you want the whole Unit Frame layout to move with your cooldowns."
L["Confirm anchoring"] = "Confirm anchoring"
L["Continue"] = "Continue"
L["Keep independent"] = "Keep independent"
L["%s detected: Global anchor follows Essential Cooldown Manager. Toggle Cooldown in MSUF Edit Mode to turn it off."] = "%s detectado: a âncora global segue o Gerenciador de Recargas Essenciais. Desative com Cooldown no modo de edição do MSUF."
L["%s detected: Cooldown Manager anchoring is off. Toggle Cooldown in MSUF Edit Mode to turn it on."] = "%s detectado: a ancoragem ao Gerenciador de Recargas está desativada. Ative com Cooldown no modo de edição do MSUF."
L["Cooldown Manager anchoring (%s)"] = "Ancoragem do Gerenciador de Recargas (%s)"
L["Global anchor (%s Anchor)"] = "Âncora global (âncora de %s)"
L["Fades all four outer edges; 0% keeps the original texture."] = "Suaviza as quatro bordas externas; 0% mantém a textura original."

-- Menu localization pass 2026-08-06: previously untranslated menu strings.
L["1:1 shows the configured aura pixel size."] = "1:1 mostra o tamanho da aura em pixels configurado."
L["Aura Options"] = "Opções de aura"
L["Aura Options and Aura Style belong to this UnitFrame. Global icon appearance: Appearance > Aura Style."] = "As Opções de aura e o Estilo Aura pertencem a este UnitFrame. Aparência global dos ícones: Aparência > Estilo Aura."
L["Below this value, remaining whole seconds may show one decimal place. Set 0 for whole seconds only."] = "Abaixo deste valor, o tempo restante pode exibir uma casa decimal. Use 0 para mostrar apenas segundos inteiros."
L["Buff Appearance"] = "Aparência dos bônus"
L["Debuff Appearance"] = "Aparência dos efeitos negativos"
L["Global Aura Appearance: Buffs"] = "Aparência global das auras: Bônus"
L["Global Aura Appearance: Debuffs"] = "Aparência global das auras: Efeitos negativos"
L["Timer colors are shared by live unit/group auras and every preview. Icon border and shadow colors live in Appearance > Auras, scoped by Aura type."] = "As cores do cronômetro são compartilhadas pelas auras ao vivo de unidade/grupo e por todas as prévias. As cores da borda e da sombra dos ícones ficam em Aparência > Auras e são configuradas por tipo de aura."
L["Click to open the setting that enables this layer."] = "Clique para abrir a configuração que ativa esta camada."
L["Controls native Aura tooltips for Spell Icons only."] = "Controla as dicas nativas de aura apenas para os Ícones de feitiços."
L["Cooldown text format"] = "Formato do texto de recarga"
L["Copies Buff, Debuff, External Defensive and Spell Icon presentation, including icon zoom, text, swipe, duration bars and ordering. Aura Options, tracked Spell Icons and the global Appearance theme remain unchanged."] = "Copia a apresentação de bônus, debilitações, defensivos externos e Ícones de feitiços, incluindo zoom do ícone, texto, varredura, barras de duração e ordenação. As Opções de aura, os Ícones de feitiços monitorados e o tema global de Aparência permanecem inalterados."
L["Copies Group Aura visibility, layout, filters, exact/category blacklists, Strata and dispel options. Aura Style and the global Appearance theme remain unchanged."] = "Copia a visibilidade, o layout, os filtros, as listas negras exatas e por categoria, a camada e as opções de remoção das auras de grupo. O Estilo Aura e o tema global de Aparência permanecem inalterados."
L["Copies this UnitFrame's Aura visibility, layout, filters, blacklists, Custom Aura setup and tracked spells. Aura Style and the global Appearance theme remain unchanged."] = "Copia a visibilidade das auras, o layout, os filtros, as listas negras, a configuração de auras personalizadas e os feitiços monitorados deste UnitFrame. O Estilo Aura e o tema global de Aparência permanecem inalterados."
L["Copies this UnitFrame's Buff, Debuff, Custom Aura, Player Defensive and Dots on Target presentation, including text, swipe, icon zoom, duration bars, Pandemic and Full-Frame effects. Aura Options and the global Appearance theme remain unchanged."] = "Copia a apresentação de bônus, debilitações, auras personalizadas, defensivos do jogador e DoTs no alvo deste UnitFrame, incluindo texto, varredura, zoom do ícone, barras de duração, pandemia e efeitos de quadro inteiro. As Opções de aura e o tema global de Aparência permanecem inalterados."
L["Drag background (%dx)"] = "Arrastar o fundo (%dx)"
L["Drag to move. Arrow keys nudge."] = "Arraste para mover. As teclas de seta ajustam com precisão."
L["EllesmereUI"] = "EllesmereUI"
L["EllesmereUI Unlock Mode"] = "Modo de desbloqueio do EllesmereUI"
L["Exact X coordinate"] = "Coordenada X exata"
L["Exact Y coordinate"] = "Coordenada Y exata"
L["Fit shows the complete aura layout."] = "Ajustar mostra o layout completo das auras."
L["Global Appearance theme selected only by Aura type. All layout, filters, timers, text and effects stay scope-aware in the corresponding UnitFrame or GroupFrame."] = "Tema global de Aparência selecionado apenas por tipo de aura. Layout, filtros, temporizadores, texto e efeitos continuam respeitando o escopo no UnitFrame ou GroupFrame correspondente."
L["Individual Style is edited here. Shared icon theme: Appearance > Aura Style."] = "O Estilo individual é editado aqui. Tema de ícones compartilhado: Aparência > Estilo Aura."
L["Layout, filters, lists and every container-specific Style live in each frame. Appearance > Aura Style owns only the global icon theme."] = "Layout, filtros, listas e cada Estilo específico do contêiner ficam em cada quadro. Aparência > Estilo Aura controla apenas o tema global de ícones."
L["Measured from the center of the previewed frame. Positive values move right. Arrow keys and dragging update the same position."] = "Medido a partir do centro do quadro em pré-visualização. Valores positivos deslocam para a direita. As teclas de seta e o arrasto atualizam a mesma posição."
L["Measured from the center of the previewed frame. Positive values move up. Arrow keys and dragging update the same position."] = "Medido a partir do centro do quadro em pré-visualização. Valores positivos deslocam para cima. As teclas de seta e o arrasto atualizam a mesma posição."
L["On (default): MSUF frames appear in EllesmereUI Unlock Mode. Turn this off to keep using the native MSUF Edit Mode. MSUF profile positions remain the source of truth."] = "Ligado (padrão): os quadros do MSUF aparecem no Modo de desbloqueio do EllesmereUI. Desligue para continuar usando o Modo de edição nativo do MSUF. As posições do perfil do MSUF continuam sendo a referência."
L["Open the frame and expand Auras. Buffs and Debuffs contain their own layout, filters, blacklists and Style; Custom 1-3, Defensive Buffs and Dots on target expose controls appropriate to their content."] = "Abra o quadro e expanda Auras. Bônus e debilitações têm layout, filtros, listas negras e Estilo próprios; Personalizada 1-3, Bônus defensivos e DoTs no alvo exibem os controles adequados ao seu conteúdo."
L["Opens the global Aura icon theme: border, shadow, colors, lane padding and native Player weapon enchants. This GroupFrame's individual Style stays here."] = "Abre o tema global de ícones de aura: borda, sombra, cores, espaçamento das faixas e encantamentos de arma nativos do jogador. O Estilo individual deste GroupFrame permanece aqui."
L["PERFORMANCE WARNING (12.1): Blizzard can run an OnUpdate every frame on each visible aura button for the full aura while it has a calculated pandemic window, not only while the warning is shown. Enable only if you accept this potentially high combat cost."] = "AVISO DE DESEMPENHO (12.1): a Blizzard pode executar um OnUpdate a cada quadro em todo botão de aura visível enquanto a aura tiver uma janela de pandemia calculada, e não apenas enquanto o aviso é exibido. Ative somente se aceitar este custo potencialmente alto em combate."
L["Paints a stand-in tint on the live GroupFrames so the overlay can be judged without a real dispellable debuff. Turns itself off when this page closes."] = "Aplica uma tonalidade provisória aos GroupFrames ativos para avaliar a sobreposição sem uma debilitação removível real. Desliga sozinho ao fechar esta página."
L["Paints a stand-in tint on the live UnitFrame so the overlay can be judged without a real dispellable debuff. Turns itself off when this page closes."] = "Aplica uma tonalidade provisória ao UnitFrame ativo para avaliar a sobreposição sem uma debilitação removível real. Desliga sozinho ao fechar esta página."
L["Position is controlled by the colored aura handle in Preview."] = "A posição é controlada pela alça de aura colorida na Pré-visualização."
L["Preview position"] = "Posição da pré-visualização"
L["Runtime Preview"] = "Pré-visualização em tempo real"
L["Runtime Preview: live GroupFrames"] = "Pré-visualização em tempo real: GroupFrames ativos"
L["Runtime Preview: live UnitFrame"] = "Pré-visualização em tempo real: UnitFrame ativo"
L["Runtime Preview: live UnitFrame (drag)"] = "Pré-visualização em tempo real: UnitFrame ativo (arrastar)"
L["Shape, border and shadow: Appearance > Aura Style > Buffs. All controls here remain Group-scope aware."] = "Forma, borda e sombra: Aparência > Estilo Aura > Bônus. Todos os controles aqui continuam respeitando o escopo de grupo."
L["Shared Aura Style"] = "Estilo Aura compartilhado"
L["Shared Aura Style: Buffs"] = "Estilo Aura compartilhado: bônus"
L["Shared Aura Style: Debuffs"] = "Estilo Aura compartilhado: debilitações"
L["Shared Preview - "] = "Pré-visualização compartilhada - "
L["Shows stand-in symbols on the live UnitFrame and lets you drag them into position without a real debuff. Turns itself off when this page closes."] = "Mostra símbolos provisórios no UnitFrame ativo e permite arrastá-los até a posição sem uma debilitação real. Desliga sozinho ao fechar esta página."
L["Spell Icon Style"] = "Estilo dos Ícones de feitiços"
L["Spell Icon tooltip"] = "Dica dos Ícones de feitiços"
L["Swipe Direction"] = "Direção da varredura"
L["This switch is shown only while EllesmereUI is loaded. Disabling it immediately returns MSUF to its own Edit Mode."] = "Esta opção só aparece enquanto o EllesmereUI está carregado. Ao desativá-la, o MSUF volta imediatamente ao seu próprio Modo de edição."
L["Use - / + or Ctrl + mouse wheel to zoom."] = "Use - / + ou Ctrl + roda do mouse para aplicar zoom."
L["Use EllesmereUI Unlock Mode for MSUF"] = "Usar o Modo de desbloqueio do EllesmereUI para o MSUF"
L["Use the colored Texture handle in Preview for exact placement."] = "Use a alça de textura colorida na Pré-visualização para o posicionamento exato."
L["Zoom changes only this preview, not your Aura settings."] = "O zoom altera apenas esta pré-visualização, não as suas configurações de aura."

