L["Adds Blizzard's temporary weapon-enchantment buttons to the Player Buff container. This is one shared setting and uses the native aura flow without an MSUF ticker or OnUpdate."] = "Adiciona os botões de encantamento temporário de arma da Blizzard ao contêiner de bônus do jogador. É uma única configuração compartilhada e usa o fluxo de auras nativo, sem temporizador nem OnUpdate do MSUF."
L["Adds an exact harmful aura ID that is missing from the curated list. The aura is still restricted to your current target and your own aura source."] = "Adiciona um ID exato de aura prejudicial que falta na lista selecionada. A aura continua restrita ao seu alvo atual e às auras de que você é a fonte."
L["Adds one exact buff to this frame's blacklist."] = "Adiciona um bônus exato à lista negra deste quadro."
L["Adds one exact buff to this group's blacklist."] = "Adiciona um bônus exato à lista negra deste grupo."
L["Adds one exact harmful aura to this Target, Focus, or Boss blacklist. Blizzard applies arbitrary SpellID filters only while the unit is not assistable."] = "Adiciona uma aura prejudicial exata à lista negra de Alvo, Foco ou Chefe. A Blizzard aplica filtros arbitrários de SpellID apenas enquanto a unidade não puder ser auxiliada."
L["All Buffs"] = "Todos os bônus"
