L["Always excludes auras without a duration. It remains active when token filters are disabled."] = "Sempre exclui auras sem duração. Continua ativo quando os filtros de identificador estão desativados."
L["Always excludes auras without a duration. This native rule wins over SpellID blacklists and whitelists."] = "Sempre exclui auras sem duração. Esta regra nativa prevalece sobre listas negras e listas brancas de SpellID."
