L["Auto: Utility Cooldowns"] = "Automático: recargas auxiliares"
L["Bar Only hides the aura icon. Icon + Bar keeps the icon and draws the duration bar on it."] = "Somente barra oculta o ícone da aura. Ícone + barra mantém o ícone e desenha a barra de duração sobre ele."
L["Bar keeps the normal statusbar. Follow Player Power mirrors the independent detached Player power shape. Orb uses a single vertical fill."] = "Barra mantém a barra de status normal. Seguir recurso do jogador espelha o formato do recurso do jogador destacado. Orbe usa um único preenchimento vertical."
L["Big Defensive"] = "Grande defensivo"
L["Big Defensive Player"] = "Grande defensivo (jogador)"
L["Blizzard castbar"] = "Barra de conjuração da Blizzard"
L["Blizzard ring + symbol"] = "Anel + símbolo da Blizzard"
L["Blizzard symbol"] = "Símbolo da Blizzard"
L["Blocks every aura in the selected curated MSUF set."] = "Bloqueia todas as auras do conjunto selecionado do MSUF."
L["Blocks only the selected aura from the curated set."] = "Bloqueia apenas a aura selecionada do conjunto."
L["Cancelable Player"] = "Cancelável (jogador)"
L["Castbar Border"] = "Borda da barra de conjuração"
L["Changes only the detached Player Powerbar. Class Resource shape on the left changes only Class Resources."] = "Altera apenas a barra de recurso do jogador destacada. O formato do recurso de classe à esquerda altera apenas os recursos de classe."
L["Class Resource Preview"] = "Pré-visualização do recurso de classe"
L["Class Resource and Player Power follow existing frames. Custom uses the slider below. Width is resolved only during layout refresh."] = "O recurso de classe e o recurso do jogador seguem os quadros existentes. Personalizado usa o controle deslizante abaixo. A largura só é resolvida na atualização do layout."
L["Controls only the second HP bar outline. Bar uses four outside border edges; shapes use their fixed edge texture. 0 disables only the outline."] = "Controla apenas o contorno da segunda barra de vida. Barra usa as quatro bordas externas; os formatos usam sua textura de borda fixa. 0 desativa somente o contorno."
L["Controls only this second HP bar. The normal Player unitframe HP text remains separate."] = "Controla apenas esta segunda barra de vida. O texto de vida normal do quadro do jogador permanece separado."
L["Controls this aura lane independently. Always / Out of Combat / Modifier / Never under Global Style > Miscellaneous affect only unit and group frames. Auras only reuse the selected Blizzard/MSUF look and cursor placement."] = "Controla esta faixa de auras de forma independente. Sempre / Fora de combate / Modificador / Nunca, em Estilo global > Diversos, afetam apenas os quadros de unidade e de grupo. As auras apenas reaproveitam o visual Blizzard/MSUF escolhido e o posicionamento do cursor."
L["Cooldown swipe direction"] = "Direção da varredura de recarga"
L["Core feature enabled by default for new profiles and once for existing profiles. It works as a normal defensive buff bar without an enabled portrait. Turn this off to disable both bar and portrait-position display."] = "Recurso principal ativado por padrão em novos perfis e uma única vez em perfis existentes. Funciona como uma barra de bônus defensivos normal mesmo sem retrato ativo. Desative para remover tanto a barra quanto a exibição na posição do retrato."
L["Crowd Control"] = "Controle de multidão"
L["Curated Retail 12.0+ and 12.1 DoT auras. Tracking is restricted to this UnitFrame's unit and your own aura source; Boss settings bind separately to boss1 through boss5."] = "Auras de DoT selecionadas para Retail 12.0+ e 12.1. O monitoramento é restrito à unidade deste UnitFrame e às auras de que você é a fonte; as configurações de Chefe se vinculam separadamente de boss1 a boss5."
L["Custom Spell ID"] = "ID de feitiço personalizado"
L["Dark Border"] = "Borda escura"
L["Disabled by default. Blizzard's native implementation enables a per-frame OnUpdate for each visible aura button as soon as that aura has a calculated pandemic window; this can begin before the warning becomes visible."] = "Desativado por padrão. A implementação nativa da Blizzard habilita um OnUpdate por quadro em cada botão de aura visível assim que essa aura tem uma janela de pandemia calculada; isso pode começar antes de o aviso ficar visível."
L["Dispellable by Group"] = "Removível pelo grupo"
L["Dispellable by Me (Raid)"] = "Removível por mim (raide)"
L["Dispellable by group"] = "Removível pelo grupo"
L["Down (Single Column)"] = "Para baixo (coluna única)"
L["Duration bar display"] = "Exibição da barra de duração"
L["Duration bar fill mode"] = "Modo de preenchimento da barra de duração"
L["Duration bar position"] = "Posição da barra de duração"
L["Edge strength of every detached Player power shape, including Bar, Round, Crystal and Orb. 0 disables only that edge."] = "Intensidade da borda de cada formato do recurso do jogador destacado, incluindo Barra, Redondo, Cristal e Orbe. 0 desativa somente essa borda."
L["Elapsed / Total"] = "Decorrido / total"
L["Enable defensive buffs"] = "Ativar bônus defensivos"
L["Enable tracked DoTs"] = "Ativar DoTs monitorados"
L["Enter a Spell ID, paste a spell link, or type a spell name. The visible helpful aura is matched even when its buff ID differs from the cast Spell ID."] = "Informe um ID de feitiço, cole um link de feitiço ou digite um nome de feitiço. A aura benéfica visível é reconhecida mesmo quando o ID do bônus difere do ID do feitiço conjurado."
L["Enter a Spell ID, paste a spell link, or type a spell name. This whitelist tracks exact Spell IDs."] = "Informe um ID de feitiço, cole um link de feitiço ou digite um nome de feitiço. Esta lista branca monitora IDs de feitiço exatos."
L["Essential cooldown viewer"] = "Visualizador de recargas essenciais"
L["Exact aura tracking"] = "Monitoramento exato de auras"
L["External Defensive"] = "Defensivo externo"
L["External Defensive Player"] = "Defensivo externo (jogador)"
L["Fill Mode"] = "Modo de preenchimento"
L["Focus off"] = "Foco desativado"
L["Focus on"] = "Foco ativado"
L["Global follows the normal MSUF health color mode. Class Color forces your class color. Dark Mode forces the configured dark bar color. HP Gradient colors only this second HP bar by current health."] = "Global segue o modo de cor de vida normal do MSUF. Class Color impõe a cor da sua classe. Dark Mode impõe a cor de barra escura configurada. HP Gradient colore apenas esta segunda barra de vida conforme a vida atual."
L["Global icon shape"] = "Formato global do ícone"
L["HP Color"] = "Cor da vida"
L["HP Outline"] = "Contorno da vida"
L["HP Shape"] = "Formato da barra de vida"
L["HP only"] = "Somente vida"
L["Healers only"] = "Somente curandeiros"
L["Hide permanent auras"] = "Ocultar auras permanentes"
L["Hides this scope's selected DoT Spell IDs from the same UnitFrame's normal Debuff container while Dots on target is enabled. Blizzard's blacklist is SpellID-based, so the same spell cast by another player is hidden there too."] = "Oculta os IDs de feitiço de DoT selecionados neste escopo do contêiner de debilitações normal do mesmo UnitFrame enquanto DoTs no alvo estiver ativo. A lista negra da Blizzard funciona por SpellID, então o mesmo feitiço conjurado por outro jogador também é ocultado ali."
L["Highest priority only"] = "Somente a de maior prioridade"
L["Icon Border & Shadow"] = "Borda e sombra do ícone"
L["Include Nameplate-only"] = "Incluir somente placas de nome"
L["Inside Left"] = "Interior esquerda"
L["Inside Right"] = "Interior direita"
L["Keeps detached Player power attached to the Class Resource bar. Player power controls are disabled while this connection is active."] = "Mantém o recurso do jogador destacado preso à barra de recurso de classe. Os controles do recurso do jogador ficam desativados enquanto esta conexão estiver ativa."
L["Keeps the configured portrait size and position as an invisible anchor so the defensive icon can remain there while the portrait itself is disabled."] = "Mantém o tamanho e a posição configurados do retrato como âncora invisível para que o ícone defensivo possa permanecer ali enquanto o próprio retrato está desativado."
L["Keeps the configured portrait size, position, and shape as an invisible anchor for tracked DoTs while the portrait itself is disabled."] = "Mantém o tamanho, a posição e o formato configurados do retrato como âncora invisível para os DoTs monitorados enquanto o próprio retrato está desativado."
L["Limits simultaneous DoT icons at the portrait from 1 to 8. Additional icons grow outward using this DoT lane's configured Growth direction."] = "Limita os ícones de DoT simultâneos no retrato de 1 a 8. Os ícones adicionais crescem para fora seguindo a direção de crescimento configurada para esta faixa de DoT."
L["Limits the number of simultaneous defensive icons at the portrait from 1 to 8. Existing profiles remain at 1 until this value is changed."] = "Limita o número de ícones defensivos simultâneos no retrato de 1 a 8. Perfis existentes permanecem em 1 até que este valor seja alterado."
L["Lists every MSUF slash command in chat, diagnostics included."] = "Lista no bate-papo todos os comandos de barra do MSUF, diagnósticos incluídos."
L["Max portrait icons"] = "Máx. de ícones no retrato"
L["Maximum debuff duration"] = "Duração máxima da debilitação"
L["Moves all detached Player power text slots together. Slot X/Y controls below add per-slot offsets."] = "Move juntos todos os campos de texto do recurso do jogador destacado. Os controles X/Y de campo abaixo adicionam deslocamentos individuais."
L["Moves the Player power bar out of the unit frame. Anchor connects it to the Class Resources stack; Sync only follows the stack width."] = "Tira a barra de recurso do jogador do quadro de unidade. Ancorar a conecta à pilha de recursos de classe; Sincronizar apenas acompanha a largura da pilha."
L["Native Aura Flow"] = "Fluxo de auras nativo"
L["Blizzard Buff & Debuff Frames"] = "Quadros de benefícios e penalidades da Blizzard"
L["Hide Blizzard Buff and Debuff Frames"] = "Ocultar os quadros de benefícios e penalidades da Blizzard"
L["Hides only Blizzard's player Buff Frame and normal Debuff icons near the minimap. Private Auras and Deadly Debuff warnings remain visible."] = "Oculta apenas o quadro de benefícios do jogador da Blizzard e os ícones normais de penalidades perto do minimapa. Auras privadas e alertas de penalidades letais permanecem visíveis."
L["Buffs hidden"] = "Benefícios ocultos"
L["Buffs visible"] = "Benefícios visíveis"
L["Debuffs hidden"] = "Penalidades ocultas"
L["Debuffs visible"] = "Penalidades visíveis"
L["Hide Blizzard Buff Frame"] = "Ocultar o quadro de benefícios da Blizzard"
L["Hide Blizzard Debuff Frame"] = "Ocultar o quadro de penalidades da Blizzard"
L["Hides Blizzard's player Buff Frame near the minimap."] = "Oculta o quadro de benefícios do jogador da Blizzard perto do minimapa."
L["Hides only Blizzard's normal Debuff icons near the minimap. Private Auras and Deadly Debuff warnings remain visible."] = "Oculta apenas os ícones normais de penalidades da Blizzard perto do minimapa. Auras privadas e alertas de penalidades letais permanecem visíveis."
L["Native size"] = "Tamanho nativo"
L["Native stealable marker"] = "Marcador nativo de roubável"
L["Native weapon enchant auras"] = "Auras nativas de encantamento de arma"
L["No roles"] = "Nenhuma função"
L["No width limit"] = "Sem limite de largura"
L["Not Cancelable"] = "Não cancelável"
L["Not Cancelable Player"] = "Não cancelável (jogador)"
L["Off shows debuffs of any duration. Otherwise, debuffs whose total duration exceeds this number of seconds are hidden."] = "Desligado mostra debilitações de qualquer duração. Caso contrário, debilitações cuja duração total ultrapasse este número de segundos são ocultadas."
L["One per dispel type"] = "Uma por tipo de remoção"
L["Opens the global Aura icon theme: border, shadow, colors, lane padding and native Player weapon enchants. This frame's container Style stays here."] = "Abre o tema global de ícones de aura: borda, sombra, cores, espaçamento das faixas e encantamentos de arma nativos do jogador. O Estilo do contêiner deste quadro permanece aqui."
L["Optional interpolation for this second HP bar. Off keeps direct native SetValue updates."] = "Interpolação opcional para esta segunda barra de vida. Desligada mantém as atualizações nativas diretas de SetValue."
L["Optional presentation mode; the Defensive Buffs feature itself does not require a portrait. With an enabled portrait, the first icon occupies it. When the portrait is off, enable the position option below to keep the icons there; otherwise MSUF safely falls back to the normal defensive bar."] = "Modo de apresentação opcional; o recurso Bônus defensivos não exige retrato. Com o retrato ativo, o primeiro ícone o ocupa. Com o retrato desligado, ative a opção de posição abaixo para manter os ícones ali; caso contrário, o MSUF volta com segurança à barra defensiva normal."
L["Orb Size"] = "Tamanho do orbe"
L["Pandemic Warning & Style"] = "Aviso de pandemia e estilo"
L["Pandemic color"] = "Cor de pandemia"
L["Places Player power text on the detached power bar. When off, the same Player power text remains positioned by the normal text layout."] = "Coloca o texto do recurso do jogador na barra de recurso destacada. Quando desligado, esse mesmo texto continua posicionado pelo layout de texto normal."
L["Places the duration bar at the top or bottom edge of the aura slot."] = "Coloca a barra de duração na borda superior ou inferior do espaço da aura."
L["Player Text Outline"] = "Contorno do texto do jogador"
L["Power Bar Outline"] = "Contorno da barra de recurso"
L["Power Text On Bar"] = "Texto do recurso na barra"
L["Power anchors use the Player power bar when it is visible; otherwise the HP bar falls back to the Class Resource anchor."] = "As âncoras de recurso usam a barra de recurso do jogador quando ela está visível; caso contrário, a barra de vida recorre à âncora do recurso de classe."
L["Raid In Combat"] = "Raide em combate"
L["Raid In Combat Player"] = "Raide em combate (jogador)"
L["Raid Player"] = "Raide (jogador)"
L["Remaining / Total"] = "Restante / total"
L["Remaining shrinks as the aura expires. Elapsed grows until the aura expires."] = "Restante encolhe conforme a aura expira. Decorrido cresce até a aura expirar."
L["Remaining time below this value uses one decimal place. Timers show unitless seconds below 1 minute and localized minutes above it. Set 0 for whole seconds only."] = "Abaixo deste valor, o tempo restante usa uma casa decimal. Os temporizadores mostram segundos sem unidade abaixo de 1 minuto e minutos localizados acima disso. Use 0 para mostrar apenas segundos inteiros."
L["Remove from blacklist"] = "Remover da lista negra"
L["Remove from whitelist"] = "Remover da lista branca"
L["Renders a second native Player health bar. The normal Player unitframe HP bar is untouched, so you can show HP twice."] = "Desenha uma segunda barra de vida nativa do jogador. A barra de vida normal do quadro do jogador não é alterada, então você pode mostrar a vida duas vezes."
L["Replaces the normal DoT lane with portrait-sized icons. The first icon exactly follows this frame's portrait width, height, and shape."] = "Substitui a faixa de DoT normal por ícones do tamanho do retrato. O primeiro ícone segue exatamente a largura, a altura e o formato do retrato deste quadro."
L["Runs /msuf reset for frame positions and visibility."] = "Executa /msuf reset para as posições e a visibilidade dos quadros."
L["Second Player HP Bar"] = "Segunda barra de vida do jogador"
L["Sets the Player font scope used by detached Power text. Player Name and HP text share this outline setting."] = "Define o escopo de fonte do jogador usado pelo texto de recurso destacado. O nome do jogador e o texto de vida compartilham esta configuração de contorno."
L["Show DoTs at portrait position"] = "Mostrar DoTs na posição do retrato"
L["Show buffs at portrait position"] = "Mostrar bônus na posição do retrato"
L["Show cooldown text on portrait"] = "Mostrar texto de recarga no retrato"
L["Shows the active defensive buff's remaining duration over its portrait icon. Blizzard updates the text natively."] = "Mostra a duração restante do bônus defensivo ativo sobre seu ícone no retrato. A Blizzard atualiza o texto de forma nativa."
L["Shows the selected class/spec resource below without changing your character, spec or saved settings."] = "Mostra abaixo o recurso da classe ou especialização selecionada sem alterar seu personagem, sua especialização ou suas configurações salvas."
L["Shows the tracked DoT's remaining duration over its portrait icon. Blizzard updates the duration natively."] = "Mostra a duração restante do DoT monitorado sobre seu ícone no retrato. A Blizzard atualiza a duração de forma nativa."
L["Simple presets for Player power text while detached power is managed by Class Resources. Custom Slots means the existing slot layout is kept until you choose a preset."] = "Predefinições simples para o texto do recurso do jogador enquanto o recurso destacado é gerenciado pelos recursos de classe. Campos personalizados mantém o layout de campos atual até você escolher uma predefinição."
L["Smooth Fill"] = "Preenchimento suave"
L["Spell Text"] = "Texto do feitiço"
L["Stops blocking this aura."] = "Para de bloquear esta aura."
L["Sync Width"] = "Sincronizar largura"
L["Tanks only"] = "Somente tanques"
L["Target DoT"] = "DoT no alvo"
L["Target off"] = "Alvo desativado"
L["Target on"] = "Alvo ativado"
L["Time Text"] = "Texto de tempo"
L["Track this predefined defensive buff. The setting applies to both the defensive bar and the optional portrait icon."] = "Monitorar este bônus defensivo predefinido. A configuração vale tanto para a barra defensiva quanto para o ícone opcional no retrato."
L["Tracked buffs viewer"] = "Visualizador de bônus monitorados"
L["Tracks your selected harmful auras on this UnitFrame's unit. Boss frames use their own boss1 through boss5 unit token."] = "Monitora as auras prejudiciais que você selecionar na unidade deste UnitFrame. Os quadros de chefe usam seus próprios identificadores de unidade, de boss1 a boss5."
L["Turns Blizzard token filters on or off for this frame. The first change automatically creates frame-specific rules; migrated Shared rules remain Shared until edited."] = "Liga ou desliga os filtros de identificador da Blizzard para este quadro. A primeira alteração cria automaticamente regras específicas do quadro; regras compartilhadas migradas continuam compartilhadas até serem editadas."
L["Unavailable cast fill"] = "Preenchimento de conjuração indisponível"
L["Up (Single Column)"] = "Para cima (coluna única)"
L["Use Player HP Text"] = "Usar o texto de vida do jogador"
L["Use portrait position while portrait is off"] = "Usar a posição do retrato com o retrato desligado"
L["Used only when this HP bar is explicitly set to Orb. Follow Player Power inherits the Player power orb size instead."] = "Usado apenas quando esta barra de vida está explicitamente definida como Orbe. Seguir recurso do jogador herda em vez disso o tamanho do orbe do recurso do jogador."
L["Uses Blizzard's 12.1 AuraButton stealable filter. It adds no MSUF aura scan, ticker, or OnUpdate."] = "Usa o filtro de roubáveis do AuraButton da Blizzard 12.1. Não adiciona nenhuma varredura de auras, temporizador ou OnUpdate do MSUF."
L["Uses Player HP text settings and copies already-rendered Player HP text when it is current. Local Text X/Y still belong to this bar."] = "Usa as configurações do texto de vida do jogador e copia o texto já desenhado quando ele está atualizado. Os valores locais de texto X/Y continuam pertencendo a esta barra."
L["Uses the Class Resource width for detached Player power without making Class Resources own the Player power controls."] = "Usa a largura do recurso de classe para o recurso do jogador destacado sem que os recursos de classe assumam os controles dele."
L["Utility cooldown viewer"] = "Visualizador de recargas auxiliares"
L["Visible behind the filled HP amount. At 100% HP the fill covers the background; Outline 0 does not disable this texture."] = "Visível atrás da parcela de vida preenchida. Com 100% de vida o preenchimento cobre o fundo; um contorno de 0 não desativa esta textura."
L["Weapon Enchants Off"] = "Encantamentos de arma desligados"
L["Weapon Enchants On"] = "Encantamentos de arma ligados"
L["While the defensive bar or portrait icon is enabled, hides every enabled tracked defensive from the normal player Buffs lane. Disabled defensive entries remain visible there."] = "Enquanto a barra defensiva ou o ícone no retrato estiver ativo, oculta da faixa de bônus normal do jogador todos os defensivos monitorados ativos. Entradas defensivas desativadas continuam visíveis ali."
L["Whole frame"] = "Quadro inteiro"
L["Width Mode"] = "Modo de largura"

-- Menu localization pass 2026-08-06 (part 3): FAQ answers and search keyword blobs that are concatenated in source.
L["Bar Background Tint Custom color in Dark Mode background backgrond backround bg backdrop opacity alpha"] = "Tonalidade de fundo da barra Cor personalizada no modo escuro fundo bg opacidade alfa background backdrop"
L["Frame Basics Enable Load Conditions Transparency Range Fade player target focus pet gone missing invisible"] = "Básico do quadro Ativar Condições de carregamento Opacidade Esmaecimento por distância jogador alvo foco lacaio ausente invisível"
L["Frame Basics Smooth fill Power Bar Smooth fill health animation power animation soft fill weiche Fuellung"] = "Básico do quadro Preenchimento suave Barra de recurso Preenchimento suave animação de vida animação de recurso smooth fill"
L["General Use MSUF group frames If this switch is off enable disable turn off hide raid party mythic"] = "Geral Usar quadros de grupo do MSUF Se esta opção estiver desligada ativar desativar ocultar raide grupo mítica"
L["Group Frames Layout Smooth health fill Health Text Power Bar Smooth fill party raid weiche Fuellung"] = "Quadros de grupo/raide Layout Preenchimento suave de vida Texto de vida Barra de recurso Preenchimento suave grupo raide smooth fill"
L["Group Frames Layout Transparency opacity fade target in combat out of combat alpha whole frame bars HP backdrop HP fill HP track preserve HP color"] = "Quadros de grupo/raide Layout Opacidade transparência esmaecer alvo em combate fora de combate alfa quadro inteiro barras vida fundo preenchimento de vida trilha de vida preservar cor de vida"
L["MSUF Edit Mode moves frames and supported castbars. Aura icon placement is controlled from each unit page > Auras or Group Frames > Auras."] = "O Modo de edição do MSUF move quadros e barras de conjuração compatíveis. A posição dos ícones de aura é controlada na página de cada unidade > Auras ou em Quadros de grupo/raide > Auras."
L["Miscellaneous misc global style language menu behavior startup notices tooltips blizzard frames minimap sounds"] = "Diversos estilo global idioma comportamento do menu avisos de inicialização dicas quadros da Blizzard minimapa sons"
L["Name Shortening Use custom settings for this scope Overrides Party Raid group frame name truncation font override shared changes"] = "Encurtamento de nome Usar configurações personalizadas para este escopo Substitui grupo raide encurtamento de nomes nos quadros de grupo substituição de fonte alterações compartilhadas"
L["Open Appearance > Auras for scope-aware cooldown text, stack text, swipe, and duration-bar styling. Timer colors remain under Colors > Auras."] = "Abra Aparência > Auras para o texto de recarga, o texto de acúmulos, a varredura e o estilo da barra de duração conforme o escopo. As cores dos temporizadores continuam em Cores > Auras."
L["Open Boss Frames > Auras > Debuffs. SpellID blacklist entries, Blizzard filters, placement, and preview live together there; styling remains under Appearance > Auras."] = "Abra Quadros de chefe > Auras > Debilitações. As entradas de lista negra por SpellID, os filtros da Blizzard, o posicionamento e a pré-visualização ficam juntos ali; o estilo continua em Aparência > Auras."
L["Open Global Style > Miscellaneous > Unitframe tooltips to control tooltip source, anchor, visibility mode, and modifier key for MSUF unit and group frames."] = "Abra Estilo global > Diversos > Dicas dos quadros de unidade para controlar a origem, a ancoragem, o modo de visibilidade e a tecla modificadora das dicas nos quadros de unidade e de grupo do MSUF."
L["Open Global Style > Miscellaneous for language, menu behavior, startup notices, tooltips, Blizzard frames, minimap icon, and sounds."] = "Abra Estilo global > Diversos para idioma, comportamento do menu, avisos de inicialização, dicas, quadros da Blizzard, ícone do minimapa e sons."
L["Open Group Frames > Layout > Range Fade. Affects chooses frame or HP fading, and the alpha sliders control out-of-range and offline opacity."] = "Abra Quadros de grupo/raide > Layout > Esmaecimento por distância. Afeta escolhe entre esmaecer o quadro ou a vida, e os controles de alfa definem a opacidade fora de alcance e off-line."
L["Open Group Frames > Layout > Transparency. Opacity controls in-combat and out-of-combat alpha; Fade target chooses whole frame, bars, HP, or backdrop. Backdrop and Health layers set base color, HP fill, and HP track opacity."] = "Abra Quadros de grupo/raide > Layout > Opacidade. Opacidade controla o alfa em combate e fora de combate; Alvo do esmaecimento escolhe quadro inteiro, barras, vida ou fundo. As camadas Fundo e Vida definem a cor base e a opacidade do preenchimento e da trilha de vida."
L["Open Group Frames > Layout for Smooth health fill. For group-frame power bars, open Group Frames > Layout > Resource Bar > Smooth fill."] = "Abra Quadros de grupo/raide > Layout para o Preenchimento suave de vida. Para as barras de recurso dos quadros de grupo, abra Quadros de grupo/raide > Layout > Barra de recursos > Preenchimento suave."
L["Open Group Frames > Layout, choose Party, Raid, or Mythic at the top, then turn off Use MSUF group frames. Use If this switch is off to choose whether Blizzard frames show normally or both frame systems stay hidden."] = "Abra Quadros de grupo/raide > Layout, escolha Grupo, Raide ou Mítica no topo e desligue Usar quadros de grupo do MSUF. Use Se esta opção estiver desligada para escolher se os quadros da Blizzard aparecem normalmente ou se os dois sistemas de quadros ficam ocultos."
L["Open Group Frames > Layout. Frame Basics and Sorting control player/self visibility and how player units are ordered in group frames."] = "Abra Quadros de grupo/raide > Layout. Básico do quadro e Classificação controlam a visibilidade do jogador e de você mesmo e a ordem das unidades nos quadros de grupo."
L["Open Group Frames > Layout. Frame Basics/Layout controls frame width, height, spacing, columns, and growth; Frame Scaling controls scale behavior."] = "Abra Quadros de grupo/raide > Layout. Básico do quadro/Layout controla largura, altura, espaçamento, colunas e crescimento; Dimensionamento do quadro controla o comportamento de escala."
L["Open Group Frames > Status & Indicators for status icons, role/leader/assist, ready check, focus glow, and other group-frame state indicators."] = "Abra Quadros de grupo/raide > Status e Indicadores para ícones de status, função/líder/assistente, verificação de prontidão, brilho de foco e outros indicadores de estado dos quadros de grupo."
L["Open Player > Auras, then turn off Buffs for the player frame. Scope-aware text and cooldown styling remains under Appearance > Auras."] = "Abra Jogador > Auras e desligue Bônus para o quadro do jogador. O estilo de texto e de recarga conforme o escopo continua em Aparência > Auras."
L["Open a unit page, then use Range Fade. It is available for Target, Target of Target, Focus, Focus Target, Pet, and Boss."] = "Abra uma página de unidade e use Esmaecimento por distância. Está disponível para Alvo, Alvo do alvo, Foco, Alvo do foco, Lacaio e Chefe."
L["Open the affected UnitFrame > Auras for icon size, placement, and filters. Use Appearance > Auras for scope-aware text and cooldown styling."] = "Abra o UnitFrame afetado > Auras para tamanho do ícone, posicionamento e filtros. Use Aparência > Auras para o texto e o estilo de recarga conforme o escopo."
L["Open the affected UnitFrame > Auras or Group Frames > Auras and reduce visible counts, timer text, or unnecessary native filter rules."] = "Abra o UnitFrame afetado > Auras ou Quadros de grupo/raide > Auras e reduza a quantidade de auras visíveis, o texto dos temporizadores ou regras de filtro nativas desnecessárias."
L["Open the affected UnitFrame > Auras, choose Buffs or Debuffs, then adjust filters, icon size, rows, caps, and spacing. Party/Raid settings are in Group Frames > Auras."] = "Abra o UnitFrame afetado > Auras, escolha Bônus ou Debilitações e ajuste filtros, tamanho do ícone, linhas, limites e espaçamento. As configurações de grupo e raide estão em Quadros de grupo/raide > Auras."
L["Open the unit page > Auras or the aura Position Popup for unit-frame aura placement. Buff/debuff icons are configured as aura layout, not moved through MSUF Edit Mode."] = "Abra a página de unidade > Auras ou a janela de posição das auras para posicionar as auras do quadro de unidade. Os ícones de bônus e debilitação são configurados como layout de auras e não são movidos pelo Modo de edição do MSUF."
L["Range Fade group frame range check raid range check party range check out of range alpha offline opacity affects frame HP"] = "Esmaecimento por distância quadro de grupo verificação de alcance raide grupo fora de alcance alfa opacidade off-line afeta quadro vida"
L["Range Fade unit frame range check range checker distance check out of range range alpha distance fade target targettarget focus focustarget pet boss"] = "Esmaecimento por distância quadro de unidade verificação de alcance verificação de distância fora de alcance alfa de alcance alvo alvo do alvo foco alvo do foco lacaio chefe"
L["Rounded Texture Rounded frame texture Unit frames Group frames Power bars Mouseover highlights rounded frames round corners"] = "Textura arredondada Textura de quadro arredondada Quadros de unidade Quadros de grupo Barras de recurso Realces ao passar o mouse quadros arredondados cantos arredondados"
L["Status icons Indicator Level Enabled Anchor X Offset Y Offset Size Layer level text level indicator show level player level target level"] = "Ícones de status Indicador Nível Ativado Ponto de ancoragem Deslocamento X Deslocamento Y Tamanho Camada texto de nível indicador de nível nível do jogador nível do alvo"
L["Text anchor offset font size layer spacing split spacing overlaps bars portraits status icons"] = "Texto ponto de ancoragem deslocamento tamanho da fonte camada ordem de desenho espaçamento espaçamento dividido sobreposições barras retratos ícones de status"
L["Use Group Frames > Layout for frame size and spacing, Auras for Buff/Debuff placement, and Status & Indicators for fixed-position status icons."] = "Use Quadros de grupo/raide > Layout para o tamanho e o espaçamento dos quadros, Auras para o posicionamento de bônus e debilitações, e Status e Indicadores para os ícones de status de posição fixa."
L["Use Group Frames pages: Layout for size, growth, sorting, bars, and text; Auras for Buff/Debuff placement, and Status & Indicators for status icons."] = "Use as páginas de Quadros de grupo/raide: Layout para tamanho, crescimento, classificação, barras e texto; Auras para o posicionamento de bônus e debilitações, e Status e Indicadores para os ícones de status."
L["Use the unit page for per-unit castbar toggles and Global Style > Castbar for shared textures, direction, text, and interrupt options."] = "Use a página de unidade para os interruptores de barra de conjuração por unidade e Estilo global > Barra de lançamento para texturas, direção, texto e opções de interrupção compartilhadas."
L["Welcome to Class Resources!\n\nWould you like to automatically set up a\ndetached Class Bar positioned above your\nEssential Cooldowns?\n\nThis configures class resource visibility,\nanchoring, width matching and detached\nPlayer Power in one click.\n\nYou can always run this later via the\n|cff00ff00Quick Setup: Class Bar|r button below."] = "Bem-vindo aos Recursos de classe!\n\nDeseja configurar automaticamente uma\nbarra de classe destacada posicionada acima das\nsuas recargas essenciais?\n\nIsso define em um clique a visibilidade do recurso\nde classe, a ancoragem, o ajuste de largura e o\nrecurso do jogador destacado.\n\nVocê sempre pode fazer isso depois pelo botão\n|cff00ff00Configuração rápida: barra de classe|r abaixo."
L["External Edit Mode"] = "External Edit Mode"
L["Show Grid2 in MSUF Edit Mode"] = "Show Grid2 in MSUF Edit Mode"
L["Grid2 Edit Mode integration"] = "Grid2 Edit Mode integration"
L["On (default): MSUF Edit Mode can move the Grid2 layout and its active detached groups. Grid2 remains the owner of its layout and saved positions."] = "On (default): MSUF Edit Mode can move the Grid2 layout and its active detached groups. Grid2 remains the owner of its layout and saved positions."
L["Show Details! in MSUF Edit Mode"] = "Show Details! in MSUF Edit Mode"
L["Details! Edit Mode integration"] = "Details! Edit Mode integration"
L["On (default): MSUF Edit Mode can move every active Details! window. Windows snapped together by Details! move as one native group."] = "On (default): MSUF Edit Mode can move every active Details! window. Windows snapped together by Details! move as one native group."
L["Turn either switch off to remove only those external movers. The third-party addon and its settings are not modified."] = "Turn either switch off to remove only those external movers. The third-party addon and its settings are not modified."

