-- Menu localization pass 2026-08-06 (part 7): entries that were still identity English.
L["Confirm anchoring"] = "Confirmar ancoragem"
L["Confirm only if you want the whole Unit Frame layout to move with your cooldowns."] = "Confirme apenas se quiser que todo o leiaute do quadro de unidade se mova junto com suas recargas."
L["Keep independent"] = "Manter independente"
L["MSUF detected %s."] = "O MSUF detectou %s."
L["MSUF will now anchor the global Unit Frame layout to Essential Cooldown Manager."] = "O MSUF vai ancorar agora o leiaute global do quadro de unidade ao Essential Cooldown Manager."
L["Nothing will move unless you confirm again in the next step. If you choose Keep independent, you can enable CDM anchoring at any time in MSUF Edit Mode or under Unit > Anchoring in the MSUF menu."] = "Nada será movido até você confirmar novamente na próxima etapa. Se escolher Manter independente, poderá ativar a ancoragem do CDM a qualquer momento no Modo de edição do MSUF ou em Unidade > Ancoragem no menu do MSUF."
L["Nothing will move unless you confirm again in the next step. You can change this later in MSUF Edit Mode."] = "Nada será movido até você confirmar novamente na próxima etapa. Você pode alterar isso depois no Modo de edição do MSUF."
L["Second confirmation for %s."] = "Segunda confirmação para %s."
L["Would you like MSUF to anchor the global Unit Frame layout to Essential Cooldown Manager?"] = "Deseja que o MSUF ancore o leiaute global do quadro de unidade ao Essential Cooldown Manager?"
L["AutoCast"] = "Conjuração automática"
L["Slot"] = "Campo"
L["Slot X"] = "Campo X"
L["Slot Y"] = "Campo Y"
-- Menu localization pass 2026-08-06 (part 7): native Player resource pings.
L["Enable native Player resource pings (12.1)"] = "Ativar pings nativos de recurso do jogador (12.1)"
L["Native Player resource pings"] = "Pings nativos de recurso do jogador"
L["Contextual pings over the MSUF Player frame can call out health and, when Blizzard supports it, mana. Blizzard does not expose separate Health/Power selection or Energy, Rage and Focus pings. The portrait keeps the normal Player unit ping and radial wheel."] = "Os pings contextuais sobre o quadro do Jogador do MSUF podem indicar vida e, quando a Blizzard oferece suporte, mana. A Blizzard não expõe uma seleção separada de Vida/Recurso nem pings de Energia, Raiva ou Foco. Sobre o retrato, o ping normal da unidade do Jogador e o menu radial permanecem disponíveis."
L["Edits the selected element's X position. Positive values move right. Arrow keys and dragging update the same position."] = "Edita a posição X do elemento selecionado. Valores positivos movem para a direita. As setas e o arrasto atualizam a mesma posição."
L["Edits the selected element's Y position. Positive values move up. Arrow keys and dragging update the same position."] = "Edita a posição Y do elemento selecionado. Valores positivos movem para cima. As setas e o arrasto atualizam a mesma posição."
L["Exact X position"] = "Posição X exata"
L["Exact Y position"] = "Posição Y exata"
L["External frame"] = "Quadro externo"
L["Next page"] = "Próxima página"
L["Previous page"] = "Página anterior"

L["UnitFrame Debuff blacklist"] = "Lista de bloqueio de efeitos negativos dos UnitFrames"
L["You can blacklist any debuff applied by the player on the %s UnitFrame using its exact Spell ID. The debuff on the unit can carry a different Spell ID than the spell you cast - use the ID from the debuff itself."] = "Você pode bloquear qualquer efeito negativo aplicado pelo jogador no UnitFrame de %s usando o ID exato do feitiço. O efeito negativo na unidade pode ter um ID de feitiço diferente do feitiço conjurado - use o ID do próprio efeito."
L["Spell ID vs. aura ID"] = "ID do feitiço vs. ID da aura"
L["The aura on the unit can use a different Spell ID than the spell you cast. Enter the ID shown on the aura itself. After adding, MSUF checks the live unit and warns when only a same-named aura with a different ID is active."] = "A aura na unidade pode usar um ID de feitiço diferente do feitiço conjurado. Informe o ID mostrado pela própria aura. Após adicionar, o MSUF verifica a unidade e avisa quando apenas uma aura de mesmo nome com outro ID está ativa."
L["%s (#%d) is active on this frame right now - blacklist entry verified."] = "%s (#%d) está ativo neste quadro agora - entrada da lista de bloqueio verificada."
L["#%d is not active on this frame, but %s is currently active as #%d. The aura's ID can differ from your cast's Spell ID."] = "#%d não está ativo neste quadro, mas %s está ativo agora como #%d. O ID da aura pode diferir do ID do feitiço conjurado."
L["Block #%d instead"] = "Bloquear #%d em vez disso"
L["Active auras on this frame"] = "Auras ativas neste quadro"
L["Shows the result of the last scan: every readable aura with the exact ID it carried, plus everything captured earlier this session. Press Rescan to scan the current unit - blocking from this list always uses the aura's own ID. Secret auras cannot be listed."] = "Mostra o resultado da última verificação: cada aura legível com seu ID exato, além de tudo capturado nesta sessão. Clique em Reescanear para verificar a unidade atual - bloquear a partir desta lista sempre usa o ID da própria aura. Auras secretas não podem ser listadas."
L["No scan yet - click Rescan"] = "Nenhuma verificação ainda - clique em Reescanear"
L["Start combat scan"] = "Iniciar verificação em combate"
L["Closes the menu and keeps scanning this frame's auras until combat ends or you press Stop. Every aura an addon can block is captured with its icon - auras Blizzard keeps secret cannot be blocked by any addon."] = "Fecha o menu e continua verificando as auras deste quadro até o combate terminar ou você clicar em Parar. Cada aura que um addon pode bloquear é capturada com seu ícone - auras mantidas em segredo pela Blizzard não podem ser bloqueadas por nenhum addon."
L["Scanning auras - creating a list"] = "Verificando auras - criando uma lista"
L["%d captured so far"] = "%d capturadas até agora"
L["%d captured so far - %d hidden by Blizzard"] = "%d capturadas até agora - %d ocultas pela Blizzard"
L["Hidden auras are Blizzard-secret - no addon can block them. Everything blockable was captured."] = "Auras ocultas são segredos da Blizzard - nenhum addon pode bloqueá-las. Tudo o que pode ser bloqueado foi capturado."
L["Blocked by Blizzard during this fight - resumes automatically. In instances, use the curated presets."] = "Bloqueado pela Blizzard durante esta luta - retoma automaticamente. Em instâncias, use os conjuntos selecionados."
L["Blizzard is blocking aura scanning right now (encounter, Mythic+, or PvP match). Use the curated presets - they cover everything blockable in instanced content."] = "A Blizzard está bloqueando a verificação de auras agora (confronto, Mítica+ ou partida JxJ). Use os conjuntos selecionados - eles cobrem tudo o que pode ser bloqueado em instâncias."
L["Scan complete: %d auras readable right now, %d captured this session. %d more are hidden by Blizzard and cannot be blocked by any addon."] = "Verificação concluída: %d auras legíveis agora, %d capturadas nesta sessão. Outras %d estão ocultas pela Blizzard - nenhum addon pode bloqueá-las."
L["Stop scan"] = "Parar"
L["Block selected aura"] = "Bloquear aura selecionada"
L["Blocks the selected aura using the exact ID it carries right now."] = "Bloqueia a aura selecionada usando o ID exato que ela usa agora."
L["No readable auras right now"] = "Nenhuma aura legível no momento"
L["Rescan"] = "Reescanear"
L["Re-reads the auras on the current unit and adds everything it sees to this session's captured list - works in combat too. Shift-click clears the captured list."] = "Relê as auras da unidade atual e adiciona tudo o que vê à lista capturada desta sessão - também funciona em combate. Shift + clique limpa a lista capturada."
L["%s - captured"] = "%s - capturada"
L["Scan complete: %d auras readable right now, %d captured this session."] = "Verificação concluída: %d auras legíveis agora, %d capturadas nesta sessão."

-- Conclusão da localização completa derivada do Menu2.
L["Aura settings are only available for Player, Target, Focus, and Boss Frames."] = "As configurações de aura estão disponíveis apenas para os quadros de Jogador, Alvo, Foco e Chefe."
L["Aura settings were skipped for unsupported UnitFrames."] = "As configurações de aura foram ignoradas para quadros de unidade não compatíveis."
L["Blizzard animated Zzz"] = "Zzz animados da Blizzard"
L["Bottom half"] = "Metade inferior"
L["Castbar settings are only available for Player, Target, Focus, and Boss Frames."] = "As configurações da barra de lançamento estão disponíveis apenas para os quadros de Jogador, Alvo, Foco e Chefe."
L["Castbar settings were skipped for UnitFrames without Castbars."] = "As configurações da barra de lançamento foram ignoradas para quadros de unidade sem barra de lançamento."
L["Changing this value selects Manual width. For Player, it also turns off Sync width to Class Resource so the new width takes effect immediately."] = "Alterar este valor seleciona Largura manual. Para o Jogador, também desativa Sincronizar largura com recurso de classe para que a nova largura tenha efeito imediatamente."
L["Current target only"] = "Somente o alvo atual"
L["Edits the selected child element's local X offset. Positive values move right. Arrow keys and dragging update the same offset."] = "Edita o deslocamento X local do elemento filho selecionado. Valores positivos o movem para a direita. As teclas de seta e o arrasto atualizam o mesmo deslocamento."
L["Edits the selected child element's local Y offset. Positive values move up. Arrow keys and dragging update the same offset."] = "Edita o deslocamento Y local do elemento filho selecionado. Valores positivos o movem para cima. As teclas de seta e o arrasto atualizam o mesmo deslocamento."
L["Exact X offset"] = "Deslocamento X exato"
L["Exact Y offset"] = "Deslocamento Y exato"
L["Full texture"] = "Textura completa"
L["Height (0 = auto)"] = "Altura (0 = automática)"
L["Highlight texture"] = "Textura de destaque"
L["No copy categories selected."] = "Nenhuma categoria de cópia selecionada."
L["Nothing was copied."] = "Nada foi copiado."
L["Outline style"] = "Estilo do contorno"
L["Rounded frames ignore True Outline and Texture styles and keep the solid outline color."] = "Quadros arredondados ignoram os estilos Contorno real e Textura e mantêm a cor sólida do contorno."
L["Texture region"] = "Região da textura"
L["Top half"] = "Metade superior"
L["True Outline"] = "Contorno real"
L["offset, size, and layer"] = "deslocamento, tamanho e camada"

L["Requires a UI reload."] = "Requer recarregar a interface."
L["Shared entries apply to every spec."] = "Entradas compartilhadas se aplicam a todas as especializações."
L["down"] = "baixo"
L["left"] = "esquerda"
L["No target"] = "Sem alvo"
L["Out of combat and no target"] = "Fora de combate e sem alvo"

L["Class Resource Text"] = "Texto de recurso de classe"
L["Click to select the value, then press Ctrl+C to copy it."] = "Clique para selecionar o valor e pressione Ctrl+C para copiá-lo."
L["HEX color"] = "Cor HEX"
L["NSRT nickname integration"] = "Integração de apelidos do NSRT"
L["Nickname Integration"] = "Integração de apelidos"
L["On (default): names supplied by Northern Sky Raid Tools replace character names on MSUF unit and group frames. Turn this off to always show character names in MSUF. NSRT and its settings are not modified."] = "Ativado (padrão): os apelidos fornecidos pelo Northern Sky Raid Tools substituem os nomes dos personagens nos quadros de unidade e grupo do MSUF. Desative esta opção para sempre mostrar os nomes dos personagens no MSUF. O NSRT e suas configurações não são modificados."

-- Native 12.1 spell-ID tooltip CVar (Global > Misc > Unitframe tooltips).
L["Show spell IDs in aura tooltips"] = "Mostrar ID de feitiço nas dicas de auras"
L["Aura tooltip spell IDs"] = "ID de feitiço nas dicas de auras"
L["On: aura tooltips show the numeric spell ID through the game's own 12.1 option, and MSUF re-enables that option after every login because the game forgets it between sessions. Off (default): MSUF never touches the game option, so other addons or a manual console setting keep control; turning this switch off clears the option once."] = "Ligado: as dicas de auras mostram a ID numérica do feitiço pela opção nativa 12.1 do jogo, e o MSUF reativa essa opção após cada login porque o jogo a esquece entre as sessões. Desligado (padrão): o MSUF nunca mexe na opção do jogo, então outros addons ou um ajuste manual de console mantêm o controle; desligar esta chave desativa a opção uma única vez."

-- Guided setup restart confirmation.
L["Run the guided setup again? The walkthrough starts over at the first step."] = "Executar a configuração guiada novamente? O passo a passo começa de novo na primeira etapa."
L["Dispel Type Colors"] = "Cores dos tipos de dissipação"
L["Magic custom"] = "Magia personalizada"
L["Magic color"] = "Cor de Magia"
L["Curse custom"] = "Maldição personalizada"
L["Curse color"] = "Cor de Maldição"
L["Disease custom"] = "Doença personalizada"
L["Disease color"] = "Cor de Doença"
L["Poison custom"] = "Veneno personalizado"
L["Poison color"] = "Cor de Veneno"
L["Bleed custom"] = "Sangramento personalizado"
L["Bleed color"] = "Cor de Sangramento"
L["Optional global overrides for harmful Magic, Curse, Disease, Poison and Bleed indicators. Off uses Blizzard's current default. The last edited type is shown first in every aura preview."] = "Cores globais opcionais para indicadores nocivos de Magia, Maldição, Doença, Veneno e Sangramento. Desativado usa o padrão atual da Blizzard. O último tipo editado aparece primeiro em todas as prévias de aura."
L["Timer and Dispel colors are shared by live unit/group auras and every preview. Icon border and shadow colors live in Appearance > Auras, scoped by Aura type."] = "As cores de temporizador e dissipação são compartilhadas pelas auras ativas de unidade e grupo e por todas as prévias. As cores de borda e sombra do ícone ficam em Aparência > Auras, por tipo de aura."
L["Cooldown timer urgency, global Dispel types, icon borders and shadows."] = "Urgência dos temporizadores, tipos globais de dissipação, bordas e sombras dos ícones."
L["Safe, Warning, Urgent, Magic, Curse, Disease, Poison, Bleed, icon border and icon shadow."] = "Seguro, Aviso, Urgente, Magia, Maldição, Doença, Veneno, Sangramento, borda e sombra do ícone."
L["While unlocked, the Combat Enter/Leave text is shown permanently as a movable handle. Drag it with the mouse or nudge it with the arrow keys. Lock it so the text only appears when entering or leaving combat."] = "Enquanto a posição estiver desbloqueada, o texto de entrar/sair de combate fica visível permanentemente como uma alça móvel. Arraste-a com o mouse ou ajuste-a com as setas do teclado. Bloqueie a posição para que o texto apareça apenas ao entrar ou sair de combate."
L["While unlocked, the Combat Timer stays visible out of combat as a movable 0:00 placeholder. Drag it with the mouse or nudge it with the arrow keys - with click-through enabled, hold ALT to drag. Lock it to freeze the position."] = "Enquanto a posição estiver desbloqueada, o cronômetro de combate permanece visível fora de combate como um marcador 0:00 móvel. Arraste-o com o mouse ou ajuste-o com as setas do teclado; com clique através ativado, segure ALT para arrastar. Bloqueie a posição para fixá-la."
end
if type(MSUF.RegisterLocaleLoader) == "function" then MSUF.RegisterLocaleLoader("ptBR", LoadLocale)
